import { useState, useEffect, useRef } from 'react';
import { SSHConnection, ConnectionGroup, CommandSnippet, ConnectionHistory, AppSettings, Toast, FileTransfer, DeployKey, Platform, TerminalApp, DEFAULT_SETTINGS, CONNECTION_COLORS, GROUP_ICONS, CONNECTION_TEMPLATES, KEYBOARD_SHORTCUTS, PortForward, PLATFORMS } from './types';
import { useLocalStorage } from './hooks/useLocalStorage';
import { useToast } from './hooks/useToast';
import { createDefaultConnection, generateSSHCommand, generatePuTTYCommand, generateRDPCommand, generateVNCCommand, generateBatchScript, generatePowerShellScript, generateSCPCommand, generateRsyncCommand, generateZmodemCommand, generateTerminalLaunch, parseSSHConfig, formatDuration, formatDate, formatFileSize, createHistoryEntry, detectPlatform, generateKeyGenCommand, generateSSHAgentSetup, generateZmodemSetup, generateGitHubSetup, generateInstallCommand } from './utils';
import { v4 as uuidv4 } from 'uuid';
import {
  Terminal, Server, Plus, Search, ChevronDown, ChevronRight, Trash2, Edit3, Copy,
  Download, Upload, Play, Globe, User, Key, Lock, Hash, FileText, Tag, StickyNote,
  Shield, Wifi, Clock, Star, StarOff, Settings, BarChart3, History, Zap, Monitor,
  FolderPlus, X, Save, Radio, Code2, FileCode, Layers, ArrowRight,
  CheckCircle2, XCircle, AlertCircle, Info, RefreshCw,
  Keyboard, ArrowUpDown, GitBranch,
  PanelLeftClose, PanelLeftOpen, MoreVertical, FileUp, FileDown, FolderOpen,
  Github, BookOpen, Send, Package, ShieldCheck, Fingerprint, KeyRound,
  MonitorSmartphone, Apple, Laptop
} from 'lucide-react';

type View = 'dashboard' | 'connections' | 'history' | 'snippets' | 'settings' | 'keygen' | 'scanner' | 'scripts' | 'shortcuts' | 'templates' | 'fileTransfer' | 'github' | 'docs';



export default function App() {
  const [connections, setConnections] = useLocalStorage<SSHConnection[]>('ssh-connections', []);
  const [groups, setGroups] = useLocalStorage<ConnectionGroup[]>('ssh-groups', [
    { id: 'prod', name: 'Production', icon: '🔒', expanded: true, color: '#ef4444' },
    { id: 'staging', name: 'Staging', icon: '⚡', expanded: true, color: '#f59e0b' },
    { id: 'dev', name: 'Development', icon: '💻', expanded: true, color: '#10b981' },
  ]);
  const [settings, setSettings] = useLocalStorage<AppSettings>('ssh-settings', { ...DEFAULT_SETTINGS, detectedPlatform: detectPlatform(), platform: detectPlatform() });
  const [snippets, setSnippets] = useLocalStorage<CommandSnippet[]>('ssh-snippets', []);
  const [history, setHistory] = useLocalStorage<ConnectionHistory[]>('ssh-history', []);
  const [transfers, setTransfers] = useLocalStorage<FileTransfer[]>('ssh-transfers', []);
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [selectedGroupId, setSelectedGroupId] = useState<string | null>(null);
  const [searchQuery, setSearchQuery] = useState('');
  const [currentView, setCurrentView] = useState<View>('dashboard');
  const [showForm, setShowForm] = useState(false);
  const [editingConn, setEditingConn] = useState<SSHConnection | null>(null);
  const [sidebarCollapsed, setSidebarCollapsed] = useState(false);
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());
  const [batchMode, setBatchMode] = useState(false);
  const { toasts, addToast, removeToast } = useToast();
  const searchRef = useRef<HTMLInputElement>(null);
  const platform = settings.platform;
  const isDark = settings.theme !== 'light';
  const selectedConn = connections.find(c => c.id === selectedId) || null;

  // Initialize sample data
  useEffect(() => {
    if (connections.length === 0) {
      const p = detectPlatform();
      const pInfo = PLATFORMS[p];
      const samples: SSHConnection[] = [
        createDefaultConnection({ name: 'Web Server (Prod)', host: '10.0.1.50', username: 'deploy', authType: 'key', keyPath: pInfo.defaultKeyPath, color: '#ef4444', tags: ['production', 'web'], notes: 'Main production web server', groupId: 'prod', totalConnections: 45, avgSessionTime: 1800000, githubEnabled: true, githubRepos: ['myorg/webapp'] }, p),
        createDefaultConnection({ name: 'Database Server', host: '10.0.1.51', username: 'dbadmin', authType: 'key', keyPath: pInfo.defaultKeyPath, color: '#ef4444', tags: ['production', 'database'], notes: 'PostgreSQL 15 primary', groupId: 'prod', totalConnections: 32, avgSessionTime: 2400000 }, p),
        createDefaultConnection({ name: 'Staging API', host: 'staging-api.example.com', port: 2222, username: 'developer', authType: 'password', color: '#f59e0b', tags: ['staging', 'api'], groupId: 'staging', totalConnections: 18 }, p),
        createDefaultConnection({ name: 'Dev VM', host: '192.168.56.10', username: 'vagrant', authType: 'key', color: '#10b981', tags: ['development', 'vagrant'], groupId: 'dev', totalConnections: 156, favorite: true, zmodemEnabled: true }, p),
        createDefaultConnection({ name: 'CI/CD Runner', host: 'ci.internal.company.com', username: 'gitlab-runner', authType: 'agent', color: '#8b5cf6', tags: ['ci', 'gitlab'], totalConnections: 8 }, p),
      ];
      setConnections(samples);
    }
  }, []);

  // Keyboard shortcuts (cross-platform)
  useEffect(() => {
    const handler = (e: KeyboardEvent) => {
      const mod = platform === 'macos' ? e.metaKey : e.ctrlKey;
      if (mod && e.key === 'n') { e.preventDefault(); setEditingConn(null); setShowForm(true); }
      if (mod && e.key === 'f') { e.preventDefault(); searchRef.current?.focus(); }
      if (mod && e.key === 'e' && selectedConn) { e.preventDefault(); setEditingConn(selectedConn); setShowForm(true); }
      if (mod && e.key === 'd' && selectedConn) { e.preventDefault(); handleDuplicate(selectedConn.id); }
      if (mod && e.key === 't') { e.preventDefault(); setCurrentView('fileTransfer'); }
      if (mod && e.key === 'g') { e.preventDefault(); setCurrentView('github'); }
      if (mod && e.key === 'h') { e.preventDefault(); setCurrentView('docs'); }
      if (e.key === 'Escape') { setShowForm(false); setEditingConn(null); }
      if (mod && e.shiftKey && e.key === 'D') { e.preventDefault(); setCurrentView('dashboard'); }
      if (mod && e.key === ',') { e.preventDefault(); setCurrentView('settings'); }
    };
    window.addEventListener('keydown', handler);
    return () => window.removeEventListener('keydown', handler);
  }, [selectedConn, platform]);

  const handleSaveConn = (conn: SSHConnection) => {
    setConnections(prev => { const exists = prev.find(c => c.id === conn.id); if (exists) return prev.map(c => c.id === conn.id ? conn : c); return [...prev, conn]; });
    setShowForm(false); setEditingConn(null); setSelectedId(conn.id);
    addToast('success', 'Saved', `Connection "${conn.name}" saved`);
  };
  const handleDeleteConn = (id: string) => {
    const conn = connections.find(c => c.id === id);
    if (settings.confirmDelete && !confirm(`Delete "${conn?.name}"?`)) return;
    setConnections(prev => prev.filter(c => c.id !== id));
    if (selectedId === id) setSelectedId(null);
    addToast('info', 'Deleted', 'Connection removed');
  };
  const handleDuplicate = (id: string) => {
    const conn = connections.find(c => c.id === id);
    if (conn) { const dup = { ...conn, id: uuidv4(), name: `${conn.name} (Copy)`, createdAt: Date.now() }; setConnections(prev => [...prev, dup]); setSelectedId(dup.id); }
  };
  const handleQuickConnect = (conn: SSHConnection) => {
    let cmd = '';
    if (conn.protocol === 'rdp') cmd = generateRDPCommand(conn, platform);
    else if (conn.protocol === 'vnc') cmd = generateVNCCommand(conn, platform);
    else cmd = generateTerminalLaunch(conn, settings);
    navigator.clipboard.writeText(cmd);
    setHistory(prev => [createHistoryEntry(conn, platform, 'success', Math.random() * 3600000), ...prev].slice(0, 100));
    setConnections(prev => prev.map(c => c.id === conn.id ? { ...c, lastConnected: Date.now(), totalConnections: c.totalConnections + 1 } : c));
    addToast('success', 'Connected', `Command copied for ${PLATFORMS[platform].name}`);
  };
  const handleBatchConnect = () => { selectedIds.forEach(id => { const conn = connections.find(c => c.id === id); if (conn) handleQuickConnect(conn); }); addToast('success', 'Batch', `Launched ${selectedIds.size} connections`); setBatchMode(false); setSelectedIds(new Set()); };
  const handleBatchDelete = () => { if (!confirm(`Delete ${selectedIds.size} connections?`)) return; setConnections(prev => prev.filter(c => !selectedIds.has(c.id))); setSelectedIds(new Set()); setBatchMode(false); };
  const handleToggleFavorite = (id: string) => { setConnections(prev => prev.map(c => c.id === id ? { ...c, favorite: !c.favorite } : c)); };
  const handleCheckStatus = (id: string) => {
    setConnections(prev => prev.map(c => c.id === id ? { ...c, status: 'unknown' } : c));
    setTimeout(() => { const online = Math.random() > 0.3; setConnections(prev => prev.map(c => c.id === id ? { ...c, status: online ? 'online' : 'offline' } : c)); addToast(online ? 'success' : 'error', 'Status', online ? 'Host reachable' : 'Host unreachable'); }, 1500);
  };
  const handleExport = () => { const data = JSON.stringify({ connections, groups, snippets, settings }, null, 2); const blob = new Blob([data], { type: 'application/json' }); const url = URL.createObjectURL(blob); const a = document.createElement('a'); a.href = url; a.download = `ssh-manager-${platform}-${new Date().toISOString().split('T')[0]}.json`; a.click(); URL.revokeObjectURL(url); addToast('success', 'Exported', 'Backup downloaded'); };
  const handleImport = () => { const input = document.createElement('input'); input.type = 'file'; input.accept = '.json'; input.onchange = (e) => { const file = (e.target as HTMLInputElement).files?.[0]; if (file) { const reader = new FileReader(); reader.onload = (ev) => { try { const data = JSON.parse(ev.target?.result as string); if (data.connections) setConnections(prev => [...prev, ...data.connections.map((c: SSHConnection) => ({ ...c, id: uuidv4() }))]); if (data.groups) setGroups(prev => [...prev, ...data.groups.map((g: ConnectionGroup) => ({ ...g, id: uuidv4() }))]); addToast('success', 'Imported', 'Data imported'); } catch { addToast('error', 'Error', 'Invalid file'); } }; reader.readAsText(file); } }; input.click(); };
  const handleImportSSHConfig = () => { const input = document.createElement('input'); input.type = 'file'; input.onchange = (e) => { const file = (e.target as HTMLInputElement).files?.[0]; if (file) { const reader = new FileReader(); reader.onload = (ev) => { const parsed = parseSSHConfig(ev.target?.result as string, platform); const newConns = parsed.map(p => createDefaultConnection(p, platform)); setConnections(prev => [...prev, ...newConns]); addToast('success', 'Imported', `${newConns.length} hosts`); }; reader.readAsText(file); } }; input.click(); };
  const toggleSelect = (id: string) => { setSelectedIds(prev => { const next = new Set(prev); next.has(id) ? next.delete(id) : next.add(id); return next; }); };
  const filteredConnections = connections.filter(conn => { const q = searchQuery.toLowerCase(); const matchesSearch = !q || conn.name.toLowerCase().includes(q) || conn.host.toLowerCase().includes(q) || conn.username.toLowerCase().includes(q) || conn.tags.some(t => t.toLowerCase().includes(q)); if (selectedGroupId) return matchesSearch && conn.groupId === selectedGroupId; return matchesSearch; });

  const PlatformIcon = () => platform === 'windows' ? <MonitorSmartphone className="w-4 h-4" /> : platform === 'macos' ? <Apple className="w-4 h-4" /> : <Laptop className="w-4 h-4" />;

  return (
    <div className={`flex h-screen overflow-hidden ${isDark ? 'bg-[#0f1117] text-gray-100' : 'bg-gray-50 text-gray-900'}`}>
      {/* Navigation Rail */}
      <nav className={`w-14 flex flex-col items-center py-3 gap-0.5 border-r ${isDark ? 'bg-[#13141f] border-[#1e2030]' : 'bg-white border-gray-200'}`}>
        <NavBtn icon={<PlatformIcon />} label={PLATFORMS[platform].name} disabled />
        <Divider isDark={isDark} />
        <NavBtn icon={<BarChart3 className="w-4 h-4" />} label="Dashboard" active={currentView === 'dashboard'} onClick={() => setCurrentView('dashboard')} />
        <NavBtn icon={<Server className="w-4 h-4" />} label="Connections" active={currentView === 'connections'} onClick={() => setCurrentView('connections')} />
        <NavBtn icon={<ArrowUpDown className="w-4 h-4" />} label="File Transfer" active={currentView === 'fileTransfer'} onClick={() => setCurrentView('fileTransfer')} />
        <NavBtn icon={<Github className="w-4 h-4" />} label="GitHub" active={currentView === 'github'} onClick={() => setCurrentView('github')} />
        <NavBtn icon={<History className="w-4 h-4" />} label="History" active={currentView === 'history'} onClick={() => setCurrentView('history')} />
        <NavBtn icon={<Code2 className="w-4 h-4" />} label="Snippets" active={currentView === 'snippets'} onClick={() => setCurrentView('snippets')} />
        <NavBtn icon={<Layers className="w-4 h-4" />} label="Templates" active={currentView === 'templates'} onClick={() => setCurrentView('templates')} />
        <NavBtn icon={<FileCode className="w-4 h-4" />} label="Scripts" active={currentView === 'scripts'} onClick={() => setCurrentView('scripts')} />
        <NavBtn icon={<Radio className="w-4 h-4" />} label="Scanner" active={currentView === 'scanner'} onClick={() => setCurrentView('scanner')} />
        <NavBtn icon={<Key className="w-4 h-4" />} label="Key Gen" active={currentView === 'keygen'} onClick={() => setCurrentView('keygen')} />
        <div className="flex-1" />
        <NavBtn icon={<BookOpen className="w-4 h-4" />} label="Docs" active={currentView === 'docs'} onClick={() => setCurrentView('docs')} />
        <NavBtn icon={<Keyboard className="w-4 h-4" />} label="Shortcuts" active={currentView === 'shortcuts'} onClick={() => setCurrentView('shortcuts')} />
        <NavBtn icon={<Settings className="w-4 h-4" />} label="Settings" active={currentView === 'settings'} onClick={() => setCurrentView('settings')} />
      </nav>

      {/* Sidebar */}
      {!sidebarCollapsed && currentView === 'connections' && (
        <div className={`w-72 border-r flex flex-col ${isDark ? 'bg-[#161822] border-[#1e2030]' : 'bg-white border-gray-200'}`}>
          <div className={`p-3 border-b ${isDark ? 'border-[#1e2030]' : 'border-gray-200'}`}>
            <div className="flex items-center gap-2 mb-2">
              <h2 className={`text-sm font-semibold flex-1 ${isDark ? 'text-gray-200' : 'text-gray-700'}`}>Connections</h2>
              <button onClick={() => setSidebarCollapsed(true)} className={`p-1 rounded ${isDark ? 'hover:bg-[#24253a]' : 'hover:bg-gray-100'}`}><PanelLeftClose className="w-4 h-4 text-gray-400" /></button>
            </div>
            <div className="relative">
              <Search className="absolute left-2.5 top-1/2 -translate-y-1/2 w-3.5 h-3.5 text-gray-500" />
              <input ref={searchRef} type="text" placeholder={`Search... (${platform === 'macos' ? '⌘' : 'Ctrl'}+F)`} value={searchQuery} onChange={e => setSearchQuery(e.target.value)} className={`w-full pl-8 pr-3 py-1.5 text-xs rounded-lg border focus:outline-none focus:ring-1 focus:ring-emerald-500/50 ${isDark ? 'bg-[#1e2030] border-[#2a2b3d] text-gray-200 placeholder-gray-500' : 'bg-gray-50 border-gray-200'}`} />
            </div>
            <div className="flex gap-1 mt-2">
              <button onClick={() => { setEditingConn(null); setShowForm(true); }} className="flex-1 flex items-center justify-center gap-1 px-2 py-1 bg-emerald-600 hover:bg-emerald-500 text-white text-xs rounded-md"><Plus className="w-3 h-3" /> New</button>
              <button onClick={handleExport} className={`px-2 py-1 text-xs rounded-md ${isDark ? 'bg-[#1e2030] text-gray-300' : 'bg-gray-100 text-gray-600'}`}><Download className="w-3 h-3" /></button>
              <button onClick={handleImport} className={`px-2 py-1 text-xs rounded-md ${isDark ? 'bg-[#1e2030] text-gray-300' : 'bg-gray-100 text-gray-600'}`}><Upload className="w-3 h-3" /></button>
              <button onClick={handleImportSSHConfig} className={`px-2 py-1 text-xs rounded-md ${isDark ? 'bg-[#1e2030] text-gray-300' : 'bg-gray-100 text-gray-600'}`}><FileText className="w-3 h-3" /></button>
              <button onClick={() => setBatchMode(!batchMode)} className={`px-2 py-1 text-xs rounded-md ${batchMode ? 'bg-amber-600 text-white' : isDark ? 'bg-[#1e2030] text-gray-300' : 'bg-gray-100 text-gray-600'}`}><Layers className="w-3 h-3" /></button>
            </div>
          </div>
          {batchMode && selectedIds.size > 0 && (<div className={`px-3 py-2 border-b flex items-center gap-2 ${isDark ? 'bg-amber-900/20 border-amber-800/30' : 'bg-amber-50 border-amber-200'}`}><span className="text-xs text-amber-400">{selectedIds.size} selected</span><button onClick={handleBatchConnect} className="px-2 py-0.5 bg-emerald-600 text-white text-xs rounded">Connect</button><button onClick={handleBatchDelete} className="px-2 py-0.5 bg-red-600 text-white text-xs rounded">Delete</button></div>)}
          <div className="px-2 pt-2 space-y-0.5">
            <SideBtn icon={<Server className="w-4 h-4" />} label="All" count={connections.length} active={selectedGroupId === null} onClick={() => setSelectedGroupId(null)} isDark={isDark} />
          </div>
          <div className="flex-1 overflow-y-auto px-2 py-2">
            {groups.map(group => { const gc = filteredConnections.filter(c => c.groupId === group.id); return (<div key={group.id} className="mb-1"><div className={`flex items-center gap-1 px-2 py-1.5 rounded-md cursor-pointer group ${isDark ? 'hover:bg-[#1e2030]' : 'hover:bg-gray-100'}`} onClick={() => setGroups(prev => prev.map(g => g.id === group.id ? { ...g, expanded: !g.expanded } : g))}><span className="text-gray-500">{group.expanded ? <ChevronDown className="w-3 h-3" /> : <ChevronRight className="w-3 h-3" />}</span><span className="text-xs">{group.icon}</span><span className={`text-xs flex-1 ${isDark ? 'text-gray-300' : 'text-gray-700'}`}>{group.name}</span><span className="text-[10px] text-gray-500">{gc.length}</span></div>{group.expanded && <div className="ml-3 space-y-0.5">{gc.map(conn => <ConnItem key={conn.id} conn={conn} isSelected={conn.id === selectedId} isBatch={batchMode} isBatchSelected={selectedIds.has(conn.id)} isDark={isDark} onSelect={() => batchMode ? toggleSelect(conn.id) : setSelectedId(conn.id)} onConnect={() => handleQuickConnect(conn)} onToggleFav={() => handleToggleFavorite(conn.id)} onCheckStatus={() => handleCheckStatus(conn.id)} />)}</div>}</div>); })}
            {filteredConnections.filter(c => !c.groupId || !groups.find(g => g.id === c.groupId)).length > 0 && (<div className="mt-2"><p className={`text-[10px] uppercase tracking-wider px-2 py-1 ${isDark ? 'text-gray-600' : 'text-gray-400'}`}>Ungrouped</p>{filteredConnections.filter(c => !c.groupId || !groups.find(g => g.id === c.groupId)).map(conn => <ConnItem key={conn.id} conn={conn} isSelected={conn.id === selectedId} isBatch={batchMode} isBatchSelected={selectedIds.has(conn.id)} isDark={isDark} onSelect={() => batchMode ? toggleSelect(conn.id) : setSelectedId(conn.id)} onConnect={() => handleQuickConnect(conn)} onToggleFav={() => handleToggleFavorite(conn.id)} onCheckStatus={() => handleCheckStatus(conn.id)} />)}</div>)}
          </div>
          <div className={`p-2 border-t ${isDark ? 'border-[#1e2030]' : 'border-gray-200'}`}><AddGroupForm groups={groups} onAdd={(g: ConnectionGroup) => setGroups(prev => [...prev, g])} isDark={isDark} /></div>
        </div>
      )}
      {sidebarCollapsed && currentView === 'connections' && (<button onClick={() => setSidebarCollapsed(false)} className={`w-8 flex items-center justify-center border-r ${isDark ? 'bg-[#161822] border-[#1e2030] hover:bg-[#1e2030]' : 'bg-white border-gray-200 hover:bg-gray-50'}`}><PanelLeftOpen className="w-4 h-4 text-gray-400" /></button>)}

      {/* Main Content */}
      <div className="flex-1 flex flex-col min-w-0 overflow-hidden">
        {currentView === 'dashboard' && <Dashboard connections={connections} groups={groups} history={history} isDark={isDark} platform={platform} onNavigate={setCurrentView} />}
        {currentView === 'connections' && (selectedConn ? <ConnDetail conn={selectedConn} groups={groups} isDark={isDark} platform={platform} settings={settings} onEdit={() => { setEditingConn(selectedConn); setShowForm(true); }} onConnect={() => handleQuickConnect(selectedConn)} onToggleFav={() => handleToggleFavorite(selectedConn.id)} onCheckStatus={() => handleCheckStatus(selectedConn.id)} /> : <WelcomeScreen isDark={isDark} platform={platform} onNew={() => { setEditingConn(null); setShowForm(true); }} count={connections.length} />)}
        {currentView === 'fileTransfer' && <FileTransferView connections={connections} isDark={isDark} platform={platform} transfers={transfers} setTransfers={setTransfers} addToast={addToast} />}
        {currentView === 'github' && <GitHubView connections={connections} isDark={isDark} platform={platform} setConnections={setConnections} addToast={addToast} />}
        {currentView === 'history' && <HistoryView history={history} isDark={isDark} onClear={() => setHistory([])} />}
        {currentView === 'snippets' && <SnippetsView snippets={snippets} isDark={isDark} onSave={(s: CommandSnippet) => setSnippets(prev => [...prev, s])} onDelete={(id: string) => setSnippets(prev => prev.filter((s: CommandSnippet) => s.id !== id))} />}
        {currentView === 'settings' && <SettingsView settings={settings} isDark={isDark} onSave={(s: AppSettings) => { setSettings(s); addToast('success', 'Settings', 'Saved'); }} />}
        {currentView === 'keygen' && <KeyGenView isDark={isDark} platform={platform} addToast={addToast} />}
        {currentView === 'scanner' && <ScannerView isDark={isDark} addToast={addToast} onImport={(conns: SSHConnection[]) => setConnections(prev => [...prev, ...conns])} />}
        {currentView === 'scripts' && <ScriptsView connections={connections} isDark={isDark} platform={platform} addToast={addToast} />}
        {currentView === 'shortcuts' && <ShortcutsView isDark={isDark} platform={platform} />}
        {currentView === 'templates' && <TemplatesView isDark={isDark} platform={platform} onApply={(t: Partial<SSHConnection>) => { const conn = createDefaultConnection(t, platform); setEditingConn(conn); setShowForm(true); }} />}
        {currentView === 'docs' && <DocsView isDark={isDark} platform={platform} settings={settings} />}
      </div>

      {showForm && <ConnForm conn={editingConn} groups={groups} isDark={isDark} platform={platform} settings={settings} onSave={handleSaveConn} onCancel={() => { setShowForm(false); setEditingConn(null); }} />}
      <div className="fixed bottom-4 right-4 z-50 space-y-2">{toasts.map(t => <ToastItem key={t.id} toast={t} onDismiss={() => removeToast(t.id)} />)}</div>
    </div>
  );
}

// ============ SHARED COMPONENTS ============
function NavBtn({ icon, label, active, onClick, disabled }: { icon: React.ReactNode; label: string; active?: boolean; onClick?: () => void; disabled?: boolean }) { return <button onClick={onClick} disabled={disabled} title={label} className={`w-10 h-10 flex items-center justify-center rounded-lg transition-colors ${active ? 'bg-emerald-600/20 text-emerald-400' : disabled ? 'text-gray-500 cursor-default' : 'text-gray-400 hover:text-gray-200 hover:bg-white/5'}`}>{icon}</button>; }
function Divider({ isDark }: { isDark: boolean }) { return <div className={`w-8 h-px my-1 ${isDark ? 'bg-[#2a2b3d]' : 'bg-gray-200'}`} />; }
function SideBtn({ icon, label, count, active, onClick, isDark }: any) { return <button onClick={onClick} className={`w-full flex items-center gap-2 px-2.5 py-1.5 rounded-md text-xs ${active ? 'bg-emerald-600/20 text-emerald-400' : isDark ? 'text-gray-300 hover:bg-[#1e2030]' : 'text-gray-700 hover:bg-gray-100'}`}>{icon}<span className="flex-1 text-left">{label}</span><span className="text-[10px] text-gray-500">{count}</span></button>; }
function ConnItem({ conn, isSelected, isBatch, isBatchSelected, isDark, onSelect, onConnect, onToggleFav, onCheckStatus }: any) { const [showMenu, setShowMenu] = useState(false); return (<div className={`relative flex items-center gap-2 px-2.5 py-1.5 rounded-md cursor-pointer group ${isSelected && !isBatch ? 'bg-emerald-600/15 border border-emerald-500/30' : isBatchSelected ? 'bg-amber-600/15 border border-amber-500/30' : `border border-transparent ${isDark ? 'hover:bg-[#1e2030]' : 'hover:bg-gray-100'}`}`} onClick={onSelect}><div className="w-2 h-2 rounded-full flex-shrink-0" style={{ backgroundColor: conn.color }} /><div className="flex-1 min-w-0"><p className={`text-xs truncate ${isDark ? 'text-gray-200' : 'text-gray-800'}`}>{conn.name}</p><p className="text-[10px] text-gray-500 truncate">{conn.username}@{conn.host}</p></div>{conn.favorite && <Star className="w-3 h-3 text-amber-400 fill-amber-400 flex-shrink-0" />} <StatusDot status={conn.status} /><div className="opacity-0 group-hover:opacity-100 flex gap-0.5"><button onClick={e => { e.stopPropagation(); onConnect(); }} className="p-1 hover:bg-emerald-500/20 rounded text-emerald-400"><Play className="w-3 h-3" /></button><button onClick={e => { e.stopPropagation(); setShowMenu(!showMenu); }} className="p-1 hover:bg-white/10 rounded text-gray-400"><MoreVertical className="w-3 h-3" /></button></div>{showMenu && (<><div className="fixed inset-0 z-40" onClick={() => setShowMenu(false)} /><div className={`absolute right-0 top-full mt-1 z-50 py-1 rounded-lg shadow-xl border min-w-[130px] ${isDark ? 'bg-[#1e2030] border-[#2a2b3d]' : 'bg-white border-gray-200'}`}><MenuBtn icon={<Star className="w-3.5 h-3.5" />} label={conn.favorite ? 'Unfavorite' : 'Favorite'} onClick={() => { onToggleFav(); setShowMenu(false); }} isDark={isDark} /><MenuBtn icon={<RefreshCw className="w-3.5 h-3.5" />} label="Check Status" onClick={() => { onCheckStatus(); setShowMenu(false); }} isDark={isDark} /></div></>)}</div>); }
function MenuBtn({ icon, label, onClick, isDark }: any) { return <button onClick={onClick} className={`w-full flex items-center gap-2 px-3 py-1.5 text-xs ${isDark ? 'text-gray-300 hover:bg-[#24253a]' : 'text-gray-700 hover:bg-gray-100'}`}>{icon} {label}</button>; }
function StatusDot({ status }: { status: string }) { return <div className={`w-1.5 h-1.5 rounded-full ${status === 'online' ? 'bg-emerald-400' : status === 'offline' ? 'bg-red-400' : 'bg-gray-500'}`} />; }
function AddGroupForm({ groups, onAdd, isDark }: any) { const [open, setOpen] = useState(false); const [name, setName] = useState(''); const [icon, setIcon] = useState('🖥️'); const [color, setColor] = useState(CONNECTION_COLORS[0]); const submit = () => { if (name.trim()) { onAdd({ id: uuidv4(), name: name.trim(), icon, expanded: true, color }); setName(''); setOpen(false); } }; if (!open) return <button onClick={() => setOpen(true)} className={`w-full flex items-center gap-2 px-2 py-1.5 rounded-md text-xs ${isDark ? 'text-gray-400 hover:bg-[#1e2030]' : 'text-gray-500 hover:bg-gray-100'}`}><FolderPlus className="w-3.5 h-3.5" /> Add Group</button>; return (<div className="space-y-2"><input type="text" value={name} onChange={e => setName(e.target.value)} onKeyDown={e => e.key === 'Enter' && submit()} placeholder="Group name..." autoFocus className={`w-full px-2 py-1 text-xs rounded border focus:outline-none ${isDark ? 'bg-[#1e2030] border-[#2a2b3d] text-gray-200' : 'bg-gray-50 border-gray-200'}`} /><div className="flex gap-1 flex-wrap">{GROUP_ICONS.slice(0, 10).map(i => <button key={i} onClick={() => setIcon(i)} className={`w-6 h-6 flex items-center justify-center rounded text-xs ${icon === i ? 'bg-emerald-600/30 ring-1 ring-emerald-500' : ''}`}>{i}</button>)}</div><div className="flex gap-1">{CONNECTION_COLORS.slice(0, 6).map(c => <button key={c} onClick={() => setColor(c)} className={`w-4 h-4 rounded-full ${color === c ? 'ring-2 ring-white ring-offset-1 ring-offset-[#161822]' : ''}`} style={{ backgroundColor: c }} />)}</div><div className="flex gap-1"><button onClick={submit} className="flex-1 px-2 py-1 bg-emerald-600 text-white text-xs rounded">Add</button><button onClick={() => setOpen(false)} className="px-2 py-1 text-xs text-gray-400">Cancel</button></div></div>); }
function inputCls(isDark: boolean) { return `w-full px-3 py-2 text-sm rounded-lg border focus:outline-none focus:ring-1 focus:ring-emerald-500/50 ${isDark ? 'bg-[#1e2030] border-[#2a2b3d] text-gray-200 placeholder-gray-500' : 'bg-gray-50 border-gray-200 text-gray-800 placeholder-gray-400'}`; }
function FF({ label, icon, children }: { label: string; icon?: React.ReactNode; children: React.ReactNode }) { return <div><label className="flex items-center gap-1.5 text-xs text-gray-400 mb-1.5">{icon}{label}</label>{children}</div>; }
function Toggle({ checked, onChange, isDark }: { checked: boolean; onChange: (v: boolean) => void; isDark: boolean }) { return <div className={`w-10 h-5 rounded-full relative cursor-pointer transition-colors ${checked ? 'bg-emerald-600' : isDark ? 'bg-[#2a2b3d]' : 'bg-gray-300'}`} onClick={() => onChange(!checked)}><div className={`absolute top-0.5 w-4 h-4 rounded-full bg-white transition-transform ${checked ? 'translate-x-5' : 'translate-x-0.5'}`} /></div>; }
function CmdBlock({ label, command, copied, onCopy, isDark }: any) { return (<div className={`rounded-lg border overflow-hidden ${isDark ? 'bg-[#0d0e17] border-[#1e2030]' : 'bg-gray-900 border-gray-700'}`}><div className={`flex items-center justify-between px-3 py-1.5 border-b ${isDark ? 'bg-[#161822] border-[#1e2030]' : 'bg-gray-800 border-gray-700'}`}><span className="text-[10px] text-gray-400">{label}</span><button onClick={onCopy} className="text-[10px] text-gray-400 hover:text-emerald-400">{copied ? '✓' : 'Copy'}</button></div><code className="block px-3 py-2 text-xs text-emerald-300 font-mono overflow-x-auto whitespace-pre-wrap">{command}</code></div>); }
function CodeBlock({ code, isDark }: { code: string; isDark: boolean }) { return <div className={`p-3 rounded-lg font-mono text-xs overflow-x-auto ${isDark ? 'bg-[#0d0e17] text-emerald-300' : 'bg-gray-900 text-emerald-300'}`}><pre className="whitespace-pre-wrap">{code}</pre></div>; }
function DocSection({ title, children, isDark }: { title: string; children: React.ReactNode; isDark: boolean }) { return <div className={`p-5 rounded-xl border ${isDark ? 'bg-[#161822] border-[#1e2030]' : 'bg-white border-gray-200'}`}><h3 className="text-sm font-semibold text-gray-200 mb-3">{title}</h3>{children}</div>; }
function StatCard({ icon, label, value, isDark }: any) { return <div className={`p-4 rounded-xl border ${isDark ? 'bg-[#161822] border-[#1e2030]' : 'bg-white border-gray-200'}`}><div className="flex items-center gap-2 mb-2">{icon}<span className="text-xs text-gray-400">{label}</span></div><p className={`text-2xl font-bold ${isDark ? 'text-white' : 'text-gray-900'}`}>{value}</p></div>; }
function QuickAction({ icon, label, onClick, isDark }: any) { return <button onClick={onClick} className={`flex items-center gap-3 p-4 rounded-xl border transition-colors ${isDark ? 'bg-[#161822] border-[#1e2030] hover:border-emerald-500/30 text-gray-300' : 'bg-white border-gray-200 hover:border-emerald-300 text-gray-700'}`}><span className="text-emerald-400">{icon}</span><span className="text-sm font-medium">{label}</span></button>; }
function FeatureCard({ icon, title, desc, isDark }: any) { return <div className={`p-3 rounded-lg border ${isDark ? 'bg-[#1e2030] border-[#2a2b3d]' : 'bg-gray-50 border-gray-200'}`}><div className="flex items-center gap-2 mb-1">{icon}<span className="text-xs font-medium text-gray-200">{title}</span></div><p className="text-[10px] text-gray-500">{desc}</p></div>; }
function DCard({ icon, label, value, isDark }: any) { return (<div className={`flex items-center gap-3 p-3 rounded-lg border ${isDark ? 'bg-[#161822] border-[#1e2030]' : 'bg-white border-gray-200'}`}><div className={`p-2 rounded-lg ${isDark ? 'bg-[#1e2030]' : 'bg-gray-100'}`}>{icon}</div><div className="flex-1 min-w-0"><p className="text-[10px] text-gray-500">{label}</p><p className={`text-sm truncate ${isDark ? 'text-gray-200' : 'text-gray-800'}`}>{value}</p></div></div>); }

// The file is very long, I'll continue with the remaining components in a more compact form
// Connection Form, Detail, and all views follow the same pattern with platform awareness

function ConnForm({ conn, groups, isDark, platform, settings, onSave, onCancel }: any) {
  const [form, setForm] = useState<SSHConnection>(conn || createDefaultConnection({}, platform));
  const [tagInput, setTagInput] = useState(''); const [cmdInput, setCmdInput] = useState(''); const [envKey, setEnvKey] = useState(''); const [envVal, setEnvVal] = useState('');
  const [tab, setTab] = useState<'basic' | 'auth' | 'tunnels' | 'startup' | 'zmodem' | 'github' | 'advanced'>('basic');
  const update = (p: Partial<SSHConnection>) => setForm((prev: SSHConnection) => ({ ...prev, ...p }));
  const tabs = [{ id: 'basic' as const, label: 'Basic', icon: <Server className="w-3.5 h-3.5" /> }, { id: 'auth' as const, label: 'Auth', icon: <Shield className="w-3.5 h-3.5" /> }, { id: 'tunnels' as const, label: 'Tunnels', icon: <GitBranch className="w-3.5 h-3.5" /> }, { id: 'startup' as const, label: 'Startup', icon: <Zap className="w-3.5 h-3.5" /> }, { id: 'zmodem' as const, label: 'Zmodem', icon: <ArrowUpDown className="w-3.5 h-3.5" /> }, { id: 'github' as const, label: 'GitHub', icon: <Github className="w-3.5 h-3.5" /> }, { id: 'advanced' as const, label: 'Advanced', icon: <Settings className="w-3.5 h-3.5" /> }];

  return (
    <div className="fixed inset-0 bg-black/70 backdrop-blur-sm z-50 flex items-center justify-center p-4" onClick={onCancel}>
      <div onClick={e => e.stopPropagation()} className={`w-full max-w-2xl max-h-[90vh] overflow-hidden rounded-xl border shadow-2xl flex flex-col ${isDark ? 'bg-[#161822] border-[#2a2b3d]' : 'bg-white border-gray-200'}`}>
        <div className={`flex items-center justify-between px-5 py-3 border-b ${isDark ? 'border-[#2a2b3d]' : 'border-gray-200'}`}><h2 className={`text-base font-semibold ${isDark ? 'text-white' : 'text-gray-900'}`}>{conn ? 'Edit' : 'New'} Connection</h2><button onClick={onCancel} className="p-1 hover:bg-white/10 rounded"><X className="w-5 h-5 text-gray-400" /></button></div>
        <div className={`flex border-b overflow-x-auto ${isDark ? 'border-[#2a2b3d]' : 'border-gray-200'}`}>{tabs.map(t => <button key={t.id} onClick={() => setTab(t.id)} className={`flex items-center gap-1.5 px-3 py-2 text-xs font-medium border-b-2 whitespace-nowrap ${tab === t.id ? 'border-emerald-500 text-emerald-400' : `border-transparent ${isDark ? 'text-gray-400' : 'text-gray-500'}`}`}>{t.icon} {t.label}</button>)}</div>
        <form onSubmit={e => { e.preventDefault(); if (form.name && form.host) onSave(form); }} className="flex-1 overflow-y-auto p-5 space-y-4">
          {tab === 'basic' && (<><FF label="Name" icon={<FileText className="w-3.5 h-3.5" />}><input type="text" value={form.name} onChange={e => update({ name: e.target.value })} required className={inputCls(isDark)} /></FF><div className="grid grid-cols-3 gap-3"><div className="col-span-2"><FF label="Host"><input type="text" value={form.host} onChange={e => update({ host: e.target.value })} required className={inputCls(isDark)} /></FF></div><FF label="Port"><input type="number" value={form.port} onChange={e => update({ port: parseInt(e.target.value) || 22 })} className={inputCls(isDark)} /></FF></div><FF label="Username"><input type="text" value={form.username} onChange={e => update({ username: e.target.value })} className={inputCls(isDark)} /></FF><FF label="Protocol"><div className="flex gap-2 flex-wrap">{(['ssh','sftp','scp','rdp','vnc','telnet','serial'] as const).map(p => <button key={p} type="button" onClick={() => update({ protocol: p })} className={`px-3 py-1.5 rounded-lg text-xs font-medium uppercase ${form.protocol === p ? 'bg-emerald-600/20 text-emerald-400 border border-emerald-500/30' : isDark ? 'bg-[#1e2030] text-gray-400 border border-[#2a2b3d]' : 'bg-gray-100 text-gray-500 border border-gray-200'}`}>{p}</button>)}</div></FF><FF label="Group"><select value={form.groupId} onChange={e => update({ groupId: e.target.value })} className={inputCls(isDark)}><option value="">No Group</option>{groups.map((g: ConnectionGroup) => <option key={g.id} value={g.id}>{g.icon} {g.name}</option>)}</select></FF><FF label="Color"><div className="flex gap-2 flex-wrap">{CONNECTION_COLORS.map(c => <button key={c} type="button" onClick={() => update({ color: c })} className={`w-6 h-6 rounded-full ${form.color === c ? 'ring-2 ring-white ring-offset-2 ring-offset-[#161822] scale-110' : 'hover:scale-110'}`} style={{ backgroundColor: c }} />)}</div></FF><FF label="Tags" icon={<Tag className="w-3.5 h-3.5" />}><div className="flex gap-2"><input type="text" value={tagInput} onChange={e => setTagInput(e.target.value)} onKeyDown={e => { if (e.key === 'Enter') { e.preventDefault(); if (tagInput.trim()) { update({ tags: [...form.tags, tagInput.trim()] }); setTagInput(''); } } }} className={inputCls(isDark)} /><button type="button" onClick={() => { if (tagInput.trim()) { update({ tags: [...form.tags, tagInput.trim()] }); setTagInput(''); } }} className="px-3 py-1.5 bg-emerald-600 text-white text-xs rounded-lg">Add</button></div>{form.tags.length > 0 && <div className="flex flex-wrap gap-1.5 mt-2">{form.tags.map((tag: string) => <span key={tag} className="inline-flex items-center gap-1 px-2 py-0.5 bg-emerald-600/20 text-emerald-400 text-xs rounded-full">{tag}<button type="button" onClick={() => update({ tags: form.tags.filter((t: string) => t !== tag) })}><X className="w-3 h-3" /></button></span>)}</div>}</FF><FF label="Notes"><textarea value={form.notes} onChange={e => update({ notes: e.target.value })} rows={2} className={`${inputCls(isDark)} resize-none`} /></FF></>)}
          {tab === 'auth' && (<><FF label="Auth Method"><div className="grid grid-cols-4 gap-2">{(['key','password','agent','certificate'] as const).map(t => <button key={t} type="button" onClick={() => update({ authType: t })} className={`px-3 py-2 rounded-lg text-xs font-medium ${form.authType === t ? 'bg-emerald-600/20 text-emerald-400 border border-emerald-500/30' : isDark ? 'bg-[#1e2030] text-gray-400 border border-[#2a2b3d]' : 'bg-gray-100 text-gray-500 border border-gray-200'}`}>{t === 'key' ? '🔑 Key' : t === 'password' ? '🔒 Password' : t === 'agent' ? '🤖 Agent' : '📜 Cert'}</button>)}</div></FF>{form.authType === 'key' && <FF label="Key Path"><input type="text" value={form.keyPath} onChange={e => update({ keyPath: e.target.value })} placeholder={PLATFORMS[platform].defaultKeyPath} className={inputCls(isDark)} /></FF>}{form.authType === 'password' && <FF label="Password"><input type="password" value={form.password} onChange={e => update({ password: e.target.value })} className={inputCls(isDark)} /></FF>}{form.authType === 'certificate' && <><FF label="Cert Path"><input type="text" value={form.certPath} onChange={e => update({ certPath: e.target.value })} className={inputCls(isDark)} /></FF><FF label="Key Path"><input type="text" value={form.keyPath} onChange={e => update({ keyPath: e.target.value })} className={inputCls(isDark)} /></FF></>}<FF label="Jump Host"><div className="grid grid-cols-3 gap-2"><input type="text" value={form.jumpHost} onChange={e => update({ jumpHost: e.target.value })} placeholder="Host" className={inputCls(isDark)} /><input type="number" value={form.jumpPort} onChange={e => update({ jumpPort: parseInt(e.target.value) || 22 })} placeholder="Port" className={inputCls(isDark)} /><input type="text" value={form.jumpUser} onChange={e => update({ jumpUser: e.target.value })} placeholder="User" className={inputCls(isDark)} /></div></FF></>)}
          {tab === 'tunnels' && (<><div className="flex items-center justify-between"><h3 className="text-sm font-medium text-gray-200">Port Forwarding</h3><button type="button" onClick={() => update({ portForwards: [...form.portForwards, { id: uuidv4(), type: 'local', localPort: 8080, remoteHost: 'localhost', remotePort: 80, enabled: true }] })} className="flex items-center gap-1 px-3 py-1.5 bg-emerald-600 text-white text-xs rounded-lg"><Plus className="w-3 h-3" /> Add</button></div>{form.portForwards.length === 0 && <p className="text-xs text-gray-500 italic">No tunnels</p>}{form.portForwards.map((pf: PortForward, idx: number) => (<div key={pf.id} className={`p-3 rounded-lg border ${isDark ? 'bg-[#1e2030] border-[#2a2b3d]' : 'bg-gray-50 border-gray-200'}`}><div className="flex items-center gap-2 mb-2"><select value={pf.type} onChange={e => { const f = [...form.portForwards]; f[idx] = { ...pf, type: e.target.value as any }; update({ portForwards: f }); }} className={`text-xs px-2 py-1 rounded border ${isDark ? 'bg-[#161822] border-[#2a2b3d] text-gray-200' : 'bg-white border-gray-200'}`}><option value="local">Local (-L)</option><option value="remote">Remote (-R)</option><option value="dynamic">Dynamic (-D)</option></select><label className="flex items-center gap-1 text-xs text-gray-400"><input type="checkbox" checked={pf.enabled} onChange={e => { const f = [...form.portForwards]; f[idx] = { ...pf, enabled: e.target.checked }; update({ portForwards: f }); }} /> Active</label><button type="button" onClick={() => update({ portForwards: form.portForwards.filter((_: any, i: number) => i !== idx) })} className="ml-auto p-1 hover:bg-red-500/20 rounded text-red-400"><Trash2 className="w-3 h-3" /></button></div><div className="grid grid-cols-3 gap-2"><div><label className="text-[10px] text-gray-500">Local Port</label><input type="number" value={pf.localPort} onChange={e => { const f = [...form.portForwards]; f[idx] = { ...pf, localPort: parseInt(e.target.value) }; update({ portForwards: f }); }} className={`w-full px-2 py-1 text-xs rounded border ${isDark ? 'bg-[#161822] border-[#2a2b3d] text-gray-200' : 'bg-white border-gray-200'}`} /></div><div><label className="text-[10px] text-gray-500">Remote Host</label><input type="text" value={pf.remoteHost} onChange={e => { const f = [...form.portForwards]; f[idx] = { ...pf, remoteHost: e.target.value }; update({ portForwards: f }); }} className={`w-full px-2 py-1 text-xs rounded border ${isDark ? 'bg-[#161822] border-[#2a2b3d] text-gray-200' : 'bg-white border-gray-200'}`} /></div><div><label className="text-[10px] text-gray-500">Remote Port</label><input type="number" value={pf.remotePort} onChange={e => { const f = [...form.portForwards]; f[idx] = { ...pf, remotePort: parseInt(e.target.value) }; update({ portForwards: f }); }} className={`w-full px-2 py-1 text-xs rounded border ${isDark ? 'bg-[#161822] border-[#2a2b3d] text-gray-200' : 'bg-white border-gray-200'}`} /></div></div></div>))}</>)}
          {tab === 'startup' && (<><FF label="Startup Commands"><div className="space-y-2">{form.startupCommands.map((cmd: string, idx: number) => <div key={idx} className="flex gap-2"><input type="text" value={cmd} onChange={e => { const c = [...form.startupCommands]; c[idx] = e.target.value; update({ startupCommands: c }); }} className={`flex-1 ${inputCls(isDark)}`} /><button type="button" onClick={() => update({ startupCommands: form.startupCommands.filter((_: string, i: number) => i !== idx) })} className="p-1.5 hover:bg-red-500/20 rounded text-red-400"><X className="w-4 h-4" /></button></div>)}</div><div className="flex gap-2 mt-2"><input type="text" value={cmdInput} onChange={e => setCmdInput(e.target.value)} onKeyDown={e => { if (e.key === 'Enter') { e.preventDefault(); if (cmdInput.trim()) { update({ startupCommands: [...form.startupCommands, cmdInput.trim()] }); setCmdInput(''); } } }} className={`flex-1 ${inputCls(isDark)}`} /><button type="button" onClick={() => { if (cmdInput.trim()) { update({ startupCommands: [...form.startupCommands, cmdInput.trim()] }); setCmdInput(''); } }} className="px-3 py-1.5 bg-emerald-600 text-white text-xs rounded-lg">Add</button></div></FF></>)}
          {tab === 'zmodem' && (<><div className={`p-4 rounded-xl border ${isDark ? 'bg-[#1e2030] border-[#2a2b3d]' : 'bg-gray-50 border-gray-200'}`}><h3 className="text-sm font-semibold text-gray-200 mb-3 flex items-center gap-2"><ArrowUpDown className="w-4 h-4 text-emerald-400" /> Zmodem / ZSSH</h3><div className="space-y-3"><label className="flex items-center justify-between"><span className="text-sm text-gray-300">Enable Zmodem</span><Toggle checked={form.zmodemEnabled} onChange={v => update({ zmodemEnabled: v })} isDark={isDark} /></label><label className="flex items-center justify-between"><span className="text-sm text-gray-300">Auto-receive</span><Toggle checked={form.zmodemAutoReceive} onChange={v => update({ zmodemAutoReceive: v })} isDark={isDark} /></label></div></div><div className={`p-4 rounded-xl border ${isDark ? 'bg-[#1e2030] border-[#2a2b3d]' : 'bg-gray-50 border-gray-200'}`}><h4 className="text-sm font-medium text-gray-200 mb-2">Platform Setup ({PLATFORMS[platform].icon} {PLATFORMS[platform].name})</h4><CodeBlock code={generateZmodemSetup(platform, settings.packageManager)} isDark={isDark} /></div></>)}
          {tab === 'github' && (<><div className={`p-4 rounded-xl border ${isDark ? 'bg-[#1e2030] border-[#2a2b3d]' : 'bg-gray-50 border-gray-200'}`}><h3 className="text-sm font-semibold text-gray-200 mb-3 flex items-center gap-2"><Github className="w-4 h-4" /> GitHub</h3><div className="space-y-3"><label className="flex items-center justify-between"><span className="text-sm text-gray-300">Enable GitHub</span><Toggle checked={form.githubEnabled} onChange={v => update({ githubEnabled: v })} isDark={isDark} /></label>{form.githubEnabled && <><div><label className="text-xs text-gray-400 mb-1 block">Token</label><input type="password" value={form.githubToken} onChange={e => update({ githubToken: e.target.value })} placeholder="ghp_xxx" className={inputCls(isDark)} /></div><div><label className="text-xs text-gray-400 mb-1 block">Repos</label><div className="space-y-1">{(form.githubRepos || []).map((repo: string, idx: number) => <div key={idx} className="flex items-center gap-2"><span className="text-xs text-gray-300 flex-1">{repo}</span><button type="button" onClick={() => update({ githubRepos: form.githubRepos?.filter((_: string, i: number) => i !== idx) })} className="text-red-400 text-xs">Remove</button></div>)}</div><button type="button" onClick={() => { const repo = prompt('owner/repo:'); if (repo) update({ githubRepos: [...(form.githubRepos || []), repo] }); }} className="mt-2 text-xs text-emerald-400">+ Add Repo</button></div></>}</div></div><div className={`p-4 rounded-xl border ${isDark ? 'bg-[#1e2030] border-[#2a2b3d]' : 'bg-gray-50 border-gray-200'}`}><h4 className="text-sm font-medium text-gray-200 mb-2">Setup Guide ({PLATFORMS[platform].icon})</h4><CodeBlock code={generateGitHubSetup(platform)} isDark={isDark} /></div></>)}
          {tab === 'advanced' && (<><div className="grid grid-cols-2 gap-4"><FF label="Timeout (s)"><input type="number" value={form.timeout} onChange={e => update({ timeout: parseInt(e.target.value) })} className={inputCls(isDark)} /></FF><FF label="Keep Alive (s)"><input type="number" value={form.keepAliveInterval} onChange={e => update({ keepAliveInterval: parseInt(e.target.value) })} className={inputCls(isDark)} /></FF></div><FF label="Font Size"><input type="number" value={form.fontSize} onChange={e => update({ fontSize: parseInt(e.target.value) })} className={inputCls(isDark)} /></FF><FF label="Theme"><div className="flex gap-2 flex-wrap">{(['default','solarized','monokai','dracula','nord','gruvbox'] as const).map(t => <button key={t} type="button" onClick={() => update({ theme: t })} className={`px-3 py-1.5 rounded-lg text-xs capitalize ${form.theme === t ? 'bg-emerald-600/20 text-emerald-400 border border-emerald-500/30' : isDark ? 'bg-[#1e2030] text-gray-400 border border-[#2a2b3d]' : 'bg-gray-100 text-gray-500 border border-gray-200'}`}>{t}</button>)}</div></FF><FF label="Encoding"><select value={form.encoding} onChange={e => update({ encoding: e.target.value })} className={inputCls(isDark)}><option value="utf-8">UTF-8</option><option value="latin-1">Latin-1</option><option value="gbk">GBK</option><option value="shift_jis">Shift-JIS</option></select></FF>{form.protocol === 'rdp' && <><FF label="RDP Resolution"><select value={form.rdpResolution} onChange={e => update({ rdpResolution: e.target.value })} className={inputCls(isDark)}><option value="1920x1080">1920x1080</option><option value="2560x1440">2560x1440</option><option value="3840x2160">3840x2160</option></select></FF><label className="flex items-center gap-2 text-xs text-gray-400"><input type="checkbox" checked={form.rdpFullScreen} onChange={e => update({ rdpFullScreen: e.target.checked })} /> Full Screen</label></>}{form.protocol === 'vnc' && <><FF label="VNC Port"><input type="number" value={form.vncPort} onChange={e => update({ vncPort: parseInt(e.target.value) })} className={inputCls(isDark)} /></FF><FF label="VNC Password"><input type="password" value={form.vncPassword} onChange={e => update({ vncPassword: e.target.value })} className={inputCls(isDark)} /></FF></>}{form.protocol === 'serial' && <div className="grid grid-cols-2 gap-4"><FF label="Baud Rate"><select value={form.serialBaudRate} onChange={e => update({ serialBaudRate: parseInt(e.target.value) })} className={inputCls(isDark)}>{[9600,19200,38400,57600,115200].map(r => <option key={r} value={r}>{r}</option>)}</select></FF><FF label="Data Bits"><select value={form.serialDataBits} onChange={e => update({ serialDataBits: parseInt(e.target.value) })} className={inputCls(isDark)}>{[5,6,7,8].map(d => <option key={d} value={d}>{d}</option>)}</select></FF></div>}<FF label="Custom Terminal Command"><input type="text" value={form.customTerminalCmd} onChange={e => update({ customTerminalCmd: e.target.value })} placeholder="Override terminal launch command..." className={inputCls(isDark)} /></FF></>)}
        </form>
        <div className={`flex gap-3 px-5 py-3 border-t ${isDark ? 'border-[#2a2b3d]' : 'border-gray-200'}`}><button type="button" onClick={onCancel} className={`flex-1 px-4 py-2 rounded-lg text-sm ${isDark ? 'bg-[#1e2030] text-gray-300' : 'bg-gray-100 text-gray-600'}`}>Cancel</button><button type="submit" onClick={() => { if (form.name && form.host) onSave(form); }} className="flex-1 flex items-center justify-center gap-2 px-4 py-2 bg-emerald-600 hover:bg-emerald-500 rounded-lg text-sm text-white font-medium"><Save className="w-4 h-4" /> {conn ? 'Update' : 'Save'}</button></div>
      </div>
    </div>
  );
}

function ConnDetail({ conn, groups, isDark, platform, settings, onEdit, onConnect, onToggleFav, onCheckStatus }: any) {
  const [copied, setCopied] = useState<string | null>(null); const [showCmds, setShowCmds] = useState(false);
  const group = groups.find((g: ConnectionGroup) => g.id === conn.groupId);
  const copy = (text: string, label: string) => { navigator.clipboard.writeText(text); setCopied(label); setTimeout(() => setCopied(null), 2000); };
  const sshCmd = generateSSHCommand(conn, platform);
  const launchCmd = generateTerminalLaunch(conn, settings);

  return (
    <div className="flex-1 h-full overflow-y-auto">
      <div className={`border-b ${isDark ? 'bg-[#161822] border-[#1e2030]' : 'bg-white border-gray-200'}`}>
        <div className="max-w-5xl mx-auto p-6">
          <div className="flex items-start justify-between">
            <div className="flex items-center gap-3"><div className="w-3 h-3 rounded-full" style={{ backgroundColor: conn.color }} /><div><div className="flex items-center gap-2"><h2 className={`text-2xl font-bold ${isDark ? 'text-white' : 'text-gray-900'}`}>{conn.name}</h2>{conn.favorite && <Star className="w-5 h-5 text-amber-400 fill-amber-400" />}<StatusDot status={conn.status} /></div><p className="text-sm text-gray-400 mt-0.5">{conn.username}@{conn.host}:{conn.port} • {conn.protocol.toUpperCase()} • {PLATFORMS[platform].icon} {PLATFORMS[platform].name}</p></div></div>
            <div className="flex gap-2"><button onClick={onCheckStatus} className={`flex items-center gap-1.5 px-3 py-2 rounded-lg text-xs ${isDark ? 'bg-[#1e2030] text-gray-300' : 'bg-gray-100 text-gray-600'}`}><RefreshCw className="w-3.5 h-3.5" /></button><button onClick={onToggleFav} className={`flex items-center gap-1.5 px-3 py-2 rounded-lg text-xs ${isDark ? 'bg-[#1e2030] text-gray-300' : 'bg-gray-100 text-gray-600'}`}>{conn.favorite ? <StarOff className="w-3.5 h-3.5" /> : <Star className="w-3.5 h-3.5" />}</button><button onClick={onEdit} className={`flex items-center gap-1.5 px-3 py-2 rounded-lg text-xs ${isDark ? 'bg-[#1e2030] text-gray-300' : 'bg-gray-100 text-gray-600'}`}><Edit3 className="w-3.5 h-3.5" /></button><button onClick={onConnect} className="flex items-center gap-1.5 px-4 py-2 bg-emerald-600 hover:bg-emerald-500 rounded-lg text-xs text-white font-medium"><Play className="w-3.5 h-3.5" /> Connect</button></div>
          </div>
          <div className="flex flex-wrap gap-2 mt-4">
            <button onClick={() => setShowCmds(!showCmds)} className={`flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs ${isDark ? 'bg-[#1e2030] text-gray-300' : 'bg-gray-100 text-gray-600'}`}><Terminal className="w-3.5 h-3.5" /> Commands</button>
            <button onClick={() => copy(sshCmd, 'ssh')} className={`flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs ${isDark ? 'bg-[#1e2030] text-gray-300' : 'bg-gray-100 text-gray-600'}`}><Copy className="w-3.5 h-3.5" /> {copied === 'ssh' ? '✓' : 'SSH'}</button>
            <button onClick={() => copy(launchCmd, 'launch')} className={`flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs ${isDark ? 'bg-[#1e2030] text-gray-300' : 'bg-gray-100 text-gray-600'}`}><Terminal className="w-3.5 h-3.5" /> {copied === 'launch' ? '✓' : 'Launch'}</button>
            {conn.zmodemEnabled && <span className="flex items-center gap-1 px-2 py-1 bg-purple-600/20 text-purple-400 text-xs rounded-full"><ArrowUpDown className="w-3 h-3" /> Zmodem</span>}
            {conn.githubEnabled && <span className="flex items-center gap-1 px-2 py-1 bg-gray-600/20 text-gray-300 text-xs rounded-full"><Github className="w-3 h-3" /> GitHub</span>}
          </div>
        </div>
      </div>
      {showCmds && (<div className={`max-w-5xl mx-auto p-6 border-b ${isDark ? 'border-[#1e2030]' : 'border-gray-200'}`}><h3 className="text-sm font-semibold text-gray-300 mb-3">Commands for {PLATFORMS[platform].icon} {PLATFORMS[platform].name}</h3><div className="grid grid-cols-1 md:grid-cols-2 gap-3"><CmdBlock label="SSH" command={sshCmd} copied={copied === 'ssh'} onCopy={() => copy(sshCmd, 'ssh')} isDark={isDark} /><CmdBlock label={`Terminal Launch (${settings.preferredTerminal})`} command={launchCmd} copied={copied === 'launch'} onCopy={() => copy(launchCmd, 'launch')} isDark={isDark} />{conn.protocol === 'rdp' && <CmdBlock label="RDP" command={generateRDPCommand(conn, platform)} copied={copied === 'rdp'} onCopy={() => copy(generateRDPCommand(conn, platform), 'rdp')} isDark={isDark} />}{conn.protocol === 'vnc' && <CmdBlock label="VNC" command={generateVNCCommand(conn, platform)} copied={copied === 'vnc'} onCopy={() => copy(generateVNCCommand(conn, platform), 'vnc')} isDark={isDark} />}{conn.zmodemEnabled && <CmdBlock label="ZSSH" command={generateZmodemCommand(conn)} copied={copied === 'zssh'} onCopy={() => copy(generateZmodemCommand(conn), 'zssh')} isDark={isDark} />}{platform === 'windows' && <CmdBlock label="PuTTY" command={generatePuTTYCommand(conn)} copied={copied === 'putty'} onCopy={() => copy(generatePuTTYCommand(conn), 'putty')} isDark={isDark} />}</div></div>)}
      <div className="max-w-5xl mx-auto p-6">
        <div className="grid grid-cols-2 md:grid-cols-3 gap-3"><DCard icon={<Globe className="w-4 h-4 text-blue-400" />} label="Host" value={conn.host} isDark={isDark} /><DCard icon={<Hash className="w-4 h-4 text-purple-400" />} label="Port" value={String(conn.port)} isDark={isDark} /><DCard icon={<User className="w-4 h-4 text-emerald-400" />} label="Username" value={conn.username} isDark={isDark} /><DCard icon={<Shield className="w-4 h-4 text-amber-400" />} label="Auth" value={conn.authType} isDark={isDark} /><DCard icon={<Wifi className="w-4 h-4 text-cyan-400" />} label="Protocol" value={conn.protocol.toUpperCase()} isDark={isDark} /><DCard icon={<BarChart3 className="w-4 h-4 text-indigo-400" />} label="Sessions" value={String(conn.totalConnections)} isDark={isDark} /></div>
        {conn.tags.length > 0 && (<div className="mt-6"><h3 className="text-sm font-semibold text-gray-400 mb-2">Tags</h3><div className="flex flex-wrap gap-2">{conn.tags.map((tag: string) => <span key={tag} className={`px-2.5 py-1 rounded-full text-xs ${isDark ? 'bg-[#1e2030] border border-[#2a2b3d] text-gray-300' : 'bg-gray-100 text-gray-600'}`}>{tag}</span>)}</div></div>)}
        {conn.notes && (<div className="mt-6"><h3 className="text-sm font-semibold text-gray-400 mb-2">Notes</h3><div className={`p-3 rounded-lg border text-sm whitespace-pre-wrap ${isDark ? 'bg-[#161822] border-[#1e2030] text-gray-300' : 'bg-gray-50 border-gray-200 text-gray-600'}`}>{conn.notes}</div></div>)}
      </div>
    </div>
  );
}

// ============ VIEWS ============
function Dashboard({ connections, groups, history, isDark, platform, onNavigate }: any) {
  const total = connections.reduce((a: number, c: SSHConnection) => a + c.totalConnections, 0);
  const gh = connections.filter((c: SSHConnection) => c.githubEnabled).length;
  const zm = connections.filter((c: SSHConnection) => c.zmodemEnabled).length;
  return (<div className="flex-1 overflow-y-auto p-8"><div className="max-w-6xl mx-auto"><div className="mb-8"><h1 className={`text-3xl font-bold ${isDark ? 'text-white' : 'text-gray-900'}`}>Dashboard</h1><p className="text-sm text-gray-400 mt-1">{PLATFORMS[platform].icon} Running on {PLATFORMS[platform].name} • SSH Manager Pro</p></div><div className="grid grid-cols-2 md:grid-cols-5 gap-4 mb-8"><StatCard icon={<Server className="w-5 h-5 text-emerald-400" />} label="Connections" value={connections.length} isDark={isDark} /><StatCard icon={<BarChart3 className="w-5 h-5 text-blue-400" />} label="Sessions" value={total} isDark={isDark} /><StatCard icon={<Github className="w-5 h-5 text-gray-300" />} label="GitHub" value={gh} isDark={isDark} /><StatCard icon={<ArrowUpDown className="w-5 h-5 text-purple-400" />} label="Zmodem" value={zm} isDark={isDark} /><StatCard icon={<Monitor className="w-5 h-5 text-cyan-400" />} label="Platform" value={PLATFORMS[platform].name} isDark={isDark} /></div><div className="grid grid-cols-2 md:grid-cols-4 gap-3 mb-8"><QuickAction icon={<Plus className="w-5 h-5" />} label="New Connection" onClick={() => onNavigate('connections')} isDark={isDark} /><QuickAction icon={<ArrowUpDown className="w-5 h-5" />} label="File Transfer" onClick={() => onNavigate('fileTransfer')} isDark={isDark} /><QuickAction icon={<Github className="w-5 h-5" />} label="GitHub" onClick={() => onNavigate('github')} isDark={isDark} /><QuickAction icon={<BookOpen className="w-5 h-5" />} label="Documentation" onClick={() => onNavigate('docs')} isDark={isDark} /></div></div></div>);
}

function FileTransferView({ connections, isDark, platform, transfers, setTransfers, addToast }: any) {
  const [selectedConn, setSelectedConn] = useState(''); const [protocol, setProtocol] = useState<'zmodem' | 'scp' | 'sftp' | 'rsync'>('scp'); const [localPath, setLocalPath] = useState(''); const [remotePath, setRemotePath] = useState(''); const [direction, setDirection] = useState<'upload' | 'download'>('upload');
  const conn = connections.find((c: SSHConnection) => c.id === selectedConn);
  const getCmd = () => { if (!conn) return ''; if (protocol === 'zmodem') return generateZmodemCommand(conn); if (protocol === 'rsync') return generateRsyncCommand(conn, localPath, remotePath, direction, platform); return generateSCPCommand(conn, localPath, remotePath, direction, platform); };
  const startTransfer = () => { if (!conn || !localPath || !remotePath) { addToast('warning', 'Missing', 'Fill all fields'); return; } const t: FileTransfer = { id: uuidv4(), connectionId: conn.id, type: direction, protocol, localPath, remotePath, fileSize: Math.floor(Math.random() * 100000000), transferredSize: 0, status: 'transferring', speed: 0, startedAt: Date.now() }; setTransfers((prev: FileTransfer[]) => [t, ...prev]); addToast('info', 'Started', `${direction} ${localPath}`); let p = 0; const iv = setInterval(() => { p += Math.random() * 20; if (p >= 100) { clearInterval(iv); setTransfers((prev: FileTransfer[]) => prev.map((x: FileTransfer) => x.id === t.id ? { ...x, status: 'completed', transferredSize: x.fileSize, speed: x.fileSize / 5, completedAt: Date.now() } : x)); addToast('success', 'Complete', 'Transfer done'); } else { setTransfers((prev: FileTransfer[]) => prev.map((x: FileTransfer) => x.id === t.id ? { ...x, transferredSize: Math.floor(x.fileSize * p / 100), speed: Math.floor(Math.random() * 5000000) } : x)); } }, 500); };
  return (<div className="flex-1 overflow-y-auto p-8"><div className="max-w-5xl mx-auto"><h1 className={`text-2xl font-bold mb-2 ${isDark ? 'text-white' : 'text-gray-900'}`}>File Transfer</h1><p className="text-sm text-gray-400 mb-6">{PLATFORMS[platform].icon} {PLATFORMS[platform].name} • Zmodem / SCP / SFTP / Rsync</p><div className="grid grid-cols-1 lg:grid-cols-2 gap-6 mb-8"><div className={`p-5 rounded-xl border ${isDark ? 'bg-[#161822] border-[#1e2030]' : 'bg-white border-gray-200'}`}><h3 className="text-sm font-semibold text-gray-200 mb-4">New Transfer</h3><div className="space-y-3"><div><label className="text-xs text-gray-400 mb-1 block">Connection</label><select value={selectedConn} onChange={e => setSelectedConn(e.target.value)} className={inputCls(isDark)}><option value="">Select...</option>{connections.map((c: SSHConnection) => <option key={c.id} value={c.id}>{c.name} ({c.host})</option>)}</select></div><div><label className="text-xs text-gray-400 mb-1 block">Protocol</label><div className="flex gap-2">{(['zmodem','scp','sftp','rsync'] as const).map(p => <button key={p} onClick={() => setProtocol(p)} className={`px-3 py-1.5 rounded-lg text-xs font-medium uppercase ${protocol === p ? 'bg-emerald-600/20 text-emerald-400 border border-emerald-500/30' : isDark ? 'bg-[#1e2030] text-gray-400 border border-[#2a2b3d]' : 'bg-gray-100 text-gray-500 border border-gray-200'}`}>{p}</button>)}</div></div><div><label className="text-xs text-gray-400 mb-1 block">Direction</label><div className="flex gap-2"><button onClick={() => setDirection('upload')} className={`flex-1 flex items-center justify-center gap-2 px-3 py-2 rounded-lg text-xs ${direction === 'upload' ? 'bg-blue-600/20 text-blue-400 border border-blue-500/30' : isDark ? 'bg-[#1e2030] text-gray-400 border border-[#2a2b3d]' : 'bg-gray-100 text-gray-500 border border-gray-200'}`}><FileUp className="w-3.5 h-3.5" /> Upload</button><button onClick={() => setDirection('download')} className={`flex-1 flex items-center justify-center gap-2 px-3 py-2 rounded-lg text-xs ${direction === 'download' ? 'bg-purple-600/20 text-purple-400 border border-purple-500/30' : isDark ? 'bg-[#1e2030] text-gray-400 border border-[#2a2b3d]' : 'bg-gray-100 text-gray-500 border border-gray-200'}`}><FileDown className="w-3.5 h-3.5" /> Download</button></div></div><div><label className="text-xs text-gray-400 mb-1 block">Local Path</label><input type="text" value={localPath} onChange={e => setLocalPath(e.target.value)} placeholder={platform === 'windows' ? 'C:\\Users\\You\\file.txt' : '~/file.txt'} className={inputCls(isDark)} /></div><div><label className="text-xs text-gray-400 mb-1 block">Remote Path</label><input type="text" value={remotePath} onChange={e => setRemotePath(e.target.value)} placeholder="/home/user/file.txt" className={inputCls(isDark)} /></div><button onClick={startTransfer} className="w-full py-2.5 bg-emerald-600 hover:bg-emerald-500 rounded-lg text-white text-sm font-medium">Start Transfer</button></div>{conn && <div className={`mt-4 p-3 rounded-lg ${isDark ? 'bg-[#0d0e17]' : 'bg-gray-900'}`}><p className="text-[10px] text-gray-400 mb-1">Command:</p><code className="text-xs text-emerald-300 font-mono break-all">{getCmd()}</code><button onClick={() => { navigator.clipboard.writeText(getCmd()); addToast('success', 'Copied', 'Command copied'); }} className="mt-1 text-[10px] text-emerald-400">Copy</button></div>}</div><div className={`p-5 rounded-xl border ${isDark ? 'bg-[#161822] border-[#1e2030]' : 'bg-white border-gray-200'}`}><h3 className="text-sm font-semibold text-gray-200 mb-4">Zmodem Setup ({PLATFORMS[platform].icon})</h3><CodeBlock code={generateZmodemSetup(platform, 'apt')} isDark={isDark} /></div></div></div></div>);
}

function GitHubView({ connections, isDark, platform, addToast }: any) {
  return (<div className="flex-1 overflow-y-auto p-8"><div className="max-w-5xl mx-auto"><div className="flex items-center gap-3 mb-6"><Github className="w-8 h-8 text-gray-200" /><div><h1 className={`text-2xl font-bold ${isDark ? 'text-white' : 'text-gray-900'}`}>GitHub Integration</h1><p className="text-sm text-gray-400">{PLATFORMS[platform].icon} {PLATFORMS[platform].name} setup</p></div></div><div className={`p-5 rounded-xl border mb-6 ${isDark ? 'bg-[#161822] border-[#1e2030]' : 'bg-white border-gray-200'}`}><h3 className="text-sm font-semibold text-gray-200 mb-4">SSH Key Setup for GitHub</h3><CodeBlock code={generateGitHubSetup(platform)} isDark={isDark} /><button onClick={() => { navigator.clipboard.writeText(generateGitHubSetup(platform)); addToast('success', 'Copied', 'Setup guide copied'); }} className="mt-3 text-xs text-emerald-400">Copy All</button></div><div className={`p-5 rounded-xl border ${isDark ? 'bg-[#161822] border-[#1e2030]' : 'bg-white border-gray-200'}`}><h3 className="text-sm font-semibold text-gray-200 mb-4">SSH Agent Setup</h3><CodeBlock code={generateSSHAgentSetup(platform)} isDark={isDark} /></div></div></div>);
}

function HistoryView({ history, isDark, onClear }: any) { return (<div className="flex-1 overflow-y-auto p-8"><div className="max-w-4xl mx-auto"><div className="flex items-center justify-between mb-6"><h1 className={`text-2xl font-bold ${isDark ? 'text-white' : 'text-gray-900'}`}>History</h1>{history.length > 0 && <button onClick={onClear} className="px-3 py-1.5 text-xs text-red-400 hover:bg-red-500/10 rounded-lg">Clear</button>}</div>{history.length === 0 ? <div className="text-center py-12"><History className="w-12 h-12 text-gray-600 mx-auto mb-3" /><p className="text-gray-500">No history</p></div> : <div className="space-y-2">{history.map((h: ConnectionHistory) => (<div key={h.id} className={`flex items-center gap-4 p-3 rounded-lg border ${isDark ? 'bg-[#161822] border-[#1e2030]' : 'bg-white border-gray-200'}`}><div className={`w-2.5 h-2.5 rounded-full ${h.status === 'success' ? 'bg-emerald-400' : 'bg-red-400'}`} /><div className="flex-1"><p className={`text-sm ${isDark ? 'text-gray-200' : 'text-gray-800'}`}>{h.connectionName}</p><p className="text-xs text-gray-500">{h.host} • {PLATFORMS[h.platform]?.icon || '🖥️'} {PLATFORMS[h.platform]?.name || h.platform}</p></div><span className="text-xs text-gray-500">{formatDuration(h.duration)}</span></div>))}</div>}</div></div>); }

function SnippetsView({ snippets, isDark, onSave, onDelete }: any) { const [name, setName] = useState(''); const [command, setCommand] = useState(''); const handleSave = () => { if (name && command) { onSave({ id: uuidv4(), name, command, description: '', tags: [], createdAt: Date.now() }); setName(''); setCommand(''); } }; return (<div className="flex-1 overflow-y-auto p-8"><div className="max-w-4xl mx-auto"><h1 className={`text-2xl font-bold mb-6 ${isDark ? 'text-white' : 'text-gray-900'}`}>Snippets</h1><div className={`p-4 rounded-xl border mb-6 ${isDark ? 'bg-[#161822] border-[#1e2030]' : 'bg-white border-gray-200'}`}><div className="flex gap-2"><input type="text" value={name} onChange={e => setName(e.target.value)} placeholder="Name..." className={inputCls(isDark)} /><input type="text" value={command} onChange={e => setCommand(e.target.value)} placeholder="Command..." className={`flex-1 font-mono ${inputCls(isDark)}`} /><button onClick={handleSave} className="px-4 py-2 bg-emerald-600 text-white text-sm rounded-lg">Save</button></div></div><div className="space-y-2">{snippets.map((s: CommandSnippet) => (<div key={s.id} className={`flex items-center gap-3 p-3 rounded-lg border ${isDark ? 'bg-[#161822] border-[#1e2030]' : 'bg-white border-gray-200'}`}><div className="flex-1"><p className={`text-sm ${isDark ? 'text-gray-200' : 'text-gray-800'}`}>{s.name}</p><code className="text-xs text-emerald-400 font-mono">{s.command}</code></div><button onClick={() => { navigator.clipboard.writeText(s.command); }} className="text-xs text-gray-400">Copy</button><button onClick={() => onDelete(s.id)} className="p-1 text-red-400"><Trash2 className="w-3.5 h-3.5" /></button></div>))}{snippets.length === 0 && <p className="text-center text-gray-500 py-8">No snippets</p>}</div></div></div>); }

function SettingsView({ settings, isDark, onSave }: any) {
  const [form, setSettings] = useState(settings);
  const update = (p: Partial<AppSettings>) => setSettings((prev: AppSettings) => ({ ...prev, ...p }));
  const pInfo = PLATFORMS[form.platform as Platform];
  return (<div className="flex-1 overflow-y-auto p-8"><div className="max-w-3xl mx-auto"><h1 className={`text-2xl font-bold mb-6 ${isDark ? 'text-white' : 'text-gray-900'}`}>Settings</h1><div className="space-y-6">
    <div className={`p-5 rounded-xl border ${isDark ? 'bg-[#161822] border-[#1e2030]' : 'bg-white border-gray-200'}`}><h3 className="text-sm font-semibold text-gray-200 mb-4">🖥️ Platform</h3><div className="grid grid-cols-3 gap-3">{(['windows','macos','linux'] as Platform[]).map(p => <button key={p} onClick={() => { const pi = PLATFORMS[p]; update({ platform: p, defaultKeyPath: pi.defaultKeyPath, sshConfigPath: pi.sshDir + '/config', sshKeyDir: pi.sshDir, downloadDir: p === 'windows' ? 'C:\\Users\\%USERNAME%\\Downloads' : '~/Downloads', preferredTerminal: pi.defaultTerminal, packageManager: pi.packageManagers[0].id, zmodemDefaultPath: p === 'windows' ? 'C:\\Users\\%USERNAME%\\Downloads' : '~/Downloads' }); }} className={`p-4 rounded-xl border text-center ${form.platform === p ? 'bg-emerald-600/20 border-emerald-500/30' : isDark ? 'bg-[#1e2030] border-[#2a2b3d]' : 'bg-gray-50 border-gray-200'}`}><span className="text-3xl block mb-2">{PLATFORMS[p].icon}</span><span className="text-sm font-medium text-gray-200">{PLATFORMS[p].name}</span></button>)}</div><p className="text-xs text-gray-500 mt-3">Detected: {PLATFORMS[settings.detectedPlatform].icon} {PLATFORMS[settings.detectedPlatform].name}</p></div>
    <div className={`p-5 rounded-xl border ${isDark ? 'bg-[#161822] border-[#1e2030]' : 'bg-white border-gray-200'}`}><h3 className="text-sm font-semibold text-gray-200 mb-4">Terminal</h3><div><label className="text-xs text-gray-400 mb-1 block">Preferred Terminal</label><div className="grid grid-cols-3 gap-2">{pInfo.terminals.map(t => <button key={t.id} onClick={() => update({ preferredTerminal: t.id })} className={`flex items-center gap-2 p-2 rounded-lg text-xs ${form.preferredTerminal === t.id ? 'bg-emerald-600/20 text-emerald-400 border border-emerald-500/30' : isDark ? 'bg-[#1e2030] text-gray-400 border border-[#2a2b3d]' : 'bg-gray-50 text-gray-500 border border-gray-200'}`}><span>{t.icon}</span>{t.name}</button>)}</div></div></div>
    <div className={`p-5 rounded-xl border ${isDark ? 'bg-[#161822] border-[#1e2030]' : 'bg-white border-gray-200'}`}><h3 className="text-sm font-semibold text-gray-200 mb-4">Package Manager</h3><div className="flex gap-2 flex-wrap">{pInfo.packageManagers.map(pm => <button key={pm.id} onClick={() => update({ packageManager: pm.id })} className={`px-3 py-2 rounded-lg text-xs ${form.packageManager === pm.id ? 'bg-emerald-600/20 text-emerald-400 border border-emerald-500/30' : isDark ? 'bg-[#1e2030] text-gray-400 border border-[#2a2b3d]' : 'bg-gray-50 text-gray-500 border border-gray-200'}`}>{pm.name}</button>)}</div></div>
    <div className={`p-5 rounded-xl border ${isDark ? 'bg-[#161822] border-[#1e2030]' : 'bg-white border-gray-200'}`}><h3 className="text-sm font-semibold text-gray-200 mb-4">Paths</h3><div className="space-y-3"><div><label className="text-xs text-gray-400 mb-1 block">SSH Config Path</label><input type="text" value={form.sshConfigPath} onChange={e => update({ sshConfigPath: e.target.value })} className={inputCls(isDark)} /></div><div><label className="text-xs text-gray-400 mb-1 block">SSH Key Directory</label><input type="text" value={form.sshKeyDir} onChange={e => update({ sshKeyDir: e.target.value })} className={inputCls(isDark)} /></div><div><label className="text-xs text-gray-400 mb-1 block">Default Download Path</label><input type="text" value={form.downloadDir} onChange={e => update({ downloadDir: e.target.value })} className={inputCls(isDark)} /></div><div><label className="text-xs text-gray-400 mb-1 block">Default Key Path</label><input type="text" value={form.defaultKeyPath} onChange={e => update({ defaultKeyPath: e.target.value })} className={inputCls(isDark)} /></div></div></div>
    <div className={`p-5 rounded-xl border ${isDark ? 'bg-[#161822] border-[#1e2030]' : 'bg-white border-gray-200'}`}><h3 className="text-sm font-semibold text-gray-200 mb-4">Appearance</h3><div className="flex gap-2">{(['dark','light','system'] as const).map(t => <button key={t} onClick={() => update({ theme: t })} className={`flex-1 px-3 py-2 rounded-lg text-sm ${form.theme === t ? 'bg-emerald-600/20 text-emerald-400 border border-emerald-500/30' : isDark ? 'bg-[#1e2030] text-gray-400 border border-[#2a2b3d]' : 'bg-gray-50 text-gray-500 border border-gray-200'}`}>{t === 'dark' ? '🌙' : t === 'light' ? '☀️' : '💻'} {t.charAt(0).toUpperCase() + t.slice(1)}</button>)}</div></div>
    <div className={`p-5 rounded-xl border ${isDark ? 'bg-[#161822] border-[#1e2030]' : 'bg-white border-gray-200'}`}><h3 className="text-sm font-semibold text-gray-200 mb-4">Behavior</h3><div className="space-y-3"><label className="flex items-center justify-between"><span className="text-sm text-gray-300">Confirm delete</span><Toggle checked={form.confirmDelete} onChange={v => update({ confirmDelete: v })} isDark={isDark} /></label><label className="flex items-center justify-between"><span className="text-sm text-gray-300">Auto-save</span><Toggle checked={form.autoSave} onChange={v => update({ autoSave: v })} isDark={isDark} /></label></div></div>
    <button onClick={() => onSave(form)} className="w-full py-3 bg-emerald-600 hover:bg-emerald-500 rounded-lg text-white font-medium">Save Settings</button>
  </div></div></div>);
}

function KeyGenView({ isDark, platform, addToast }: any) {
  const [keyType, setKeyType] = useState<'ed25519' | 'rsa' | 'ecdsa'>('ed25519'); const [bits, setBits] = useState(4096); const [comment, setComment] = useState(''); const [generated, setGenerated] = useState(false);
  const cmd = generateKeyGenCommand(keyType, bits, comment, platform);
  return (<div className="flex-1 overflow-y-auto p-8"><div className="max-w-3xl mx-auto"><h1 className={`text-2xl font-bold mb-2 ${isDark ? 'text-white' : 'text-gray-900'}`}>SSH Key Generator</h1><p className="text-sm text-gray-400 mb-6">{PLATFORMS[platform].icon} {PLATFORMS[platform].name}</p><div className={`p-6 rounded-xl border ${isDark ? 'bg-[#161822] border-[#1e2030]' : 'bg-white border-gray-200'}`}><div className="grid grid-cols-2 gap-4 mb-4"><div><label className="text-xs text-gray-400 mb-1 block">Key Type</label><div className="flex gap-2">{(['ed25519','rsa','ecdsa'] as const).map(t => <button key={t} onClick={() => setKeyType(t)} className={`flex-1 px-3 py-2 rounded-lg text-xs font-medium uppercase ${keyType === t ? 'bg-emerald-600/20 text-emerald-400 border border-emerald-500/30' : isDark ? 'bg-[#1e2030] text-gray-400 border border-[#2a2b3d]' : 'bg-gray-100 text-gray-500 border border-gray-200'}`}>{t}</button>)}</div></div>{keyType === 'rsa' && <div><label className="text-xs text-gray-400 mb-1 block">Bits</label><select value={bits} onChange={e => setBits(parseInt(e.target.value))} className={inputCls(isDark)}><option value={2048}>2048</option><option value={3072}>3072</option><option value={4096}>4096</option></select></div>}</div><div className="mb-4"><label className="text-xs text-gray-400 mb-1 block">Comment</label><input type="text" value={comment} onChange={e => setComment(e.target.value)} placeholder="user@email.com" className={inputCls(isDark)} /></div><button onClick={() => { setGenerated(true); addToast('success', 'Generated', 'Command ready'); }} className="w-full py-3 bg-emerald-600 hover:bg-emerald-500 rounded-lg text-white font-medium">Generate</button>{generated && <div className="mt-4"><CodeBlock code={cmd} isDark={isDark} /><button onClick={() => { navigator.clipboard.writeText(cmd); addToast('success', 'Copied', 'Command copied'); }} className="mt-2 text-xs text-emerald-400">Copy</button><div className="mt-4"><h4 className="text-sm font-medium text-gray-200 mb-2">SSH Agent Setup</h4><CodeBlock code={generateSSHAgentSetup(platform)} isDark={isDark} /></div></div>}</div></div></div>);
}

function ScannerView({ isDark, addToast, onImport }: any) { const [subnet, setSubnet] = useState('192.168.1'); const [port, setPort] = useState(22); const [scanning, setScanning] = useState(false); const [results, setResults] = useState<{ ip: string; open: boolean }[]>([]); const handleScan = () => { setScanning(true); setResults([]); const ips = Array.from({ length: 20 }, (_, i) => `${subnet}.${i + 1}`); let idx = 0; const iv = setInterval(() => { if (idx >= ips.length) { clearInterval(iv); setScanning(false); return; } setResults(prev => [...prev, { ip: ips[idx], open: Math.random() > 0.7 }]); idx++; }, 200); }; return (<div className="flex-1 overflow-y-auto p-8"><div className="max-w-4xl mx-auto"><h1 className={`text-2xl font-bold mb-6 ${isDark ? 'text-white' : 'text-gray-900'}`}>Network Scanner</h1><div className={`p-5 rounded-xl border mb-6 ${isDark ? 'bg-[#161822] border-[#1e2030]' : 'bg-white border-gray-200'}`}><div className="flex gap-3 items-end"><div className="flex-1"><label className="text-xs text-gray-400 mb-1 block">Subnet</label><input type="text" value={subnet} onChange={e => setSubnet(e.target.value)} className={inputCls(isDark)} /></div><div className="w-24"><label className="text-xs text-gray-400 mb-1 block">Port</label><input type="number" value={port} onChange={e => setPort(parseInt(e.target.value))} className={inputCls(isDark)} /></div><button onClick={handleScan} disabled={scanning} className="px-6 py-2 bg-emerald-600 hover:bg-emerald-500 disabled:opacity-50 rounded-lg text-white text-sm">{scanning ? 'Scanning...' : 'Scan'}</button></div></div>{results.length > 0 && <div className={`rounded-xl border overflow-hidden ${isDark ? 'bg-[#161822] border-[#1e2030]' : 'bg-white border-gray-200'}`}><div className={`px-4 py-3 border-b ${isDark ? 'border-[#1e2030]' : 'border-gray-200'}`}><span className="text-sm text-gray-300">Results ({results.filter(r => r.open).length} open)</span></div><div className="max-h-96 overflow-y-auto">{results.map((r, i) => <div key={i} className={`flex items-center gap-3 px-4 py-2 border-b last:border-0 ${isDark ? 'border-[#1e2030]' : 'border-gray-100'}`}><div className={`w-2 h-2 rounded-full ${r.open ? 'bg-emerald-400' : 'bg-gray-600'}`} /><span className={`text-sm font-mono flex-1 ${isDark ? 'text-gray-200' : 'text-gray-800'}`}>{r.ip}</span><span className="text-xs text-gray-500">{r.open ? 'Open' : 'Closed'}</span></div>)}</div></div>}</div></div>); }

function ScriptsView({ connections, isDark, platform, addToast }: any) { const [selected, setSelected] = useState<Set<string>>(new Set()); const [scriptType, setScriptType] = useState<'bat' | 'ps1' | 'sh'>('sh'); const toggle = (id: string) => { setSelected(prev => { const n = new Set(prev); n.has(id) ? n.delete(id) : n.add(id); return n; }); }; const generate = () => { const conns = connections.filter((c: SSHConnection) => selected.has(c.id)); if (conns.length === 0) { addToast('warning', 'Select', 'Choose connections'); return; } let script = ''; const ext = platform === 'windows' ? 'bat' : 'sh'; if (scriptType === 'bat' || (scriptType === 'sh' && platform === 'windows')) script = generateBatchScript(conns, platform); else if (scriptType === 'ps1') script = generatePowerShellScript(conns, platform); else script = generateBatchScript(conns, platform); const blob = new Blob([script], { type: 'text/plain' }); const url = URL.createObjectURL(blob); const a = document.createElement('a'); a.href = url; a.download = `ssh-connect.${ext}`; a.click(); URL.revokeObjectURL(url); addToast('success', 'Generated', `Script for ${PLATFORMS[platform].name}`); }; return (<div className="flex-1 overflow-y-auto p-8"><div className="max-w-4xl mx-auto"><h1 className={`text-2xl font-bold mb-2 ${isDark ? 'text-white' : 'text-gray-900'}`}>Script Generator</h1><p className="text-sm text-gray-400 mb-6">{PLATFORMS[platform].icon} {PLATFORMS[platform].name} scripts</p><div className={`p-5 rounded-xl border ${isDark ? 'bg-[#161822] border-[#1e2030]' : 'bg-white border-gray-200'}`}><div className="flex items-center gap-4 mb-4"><span className="text-sm text-gray-400">Type:</span>{(['bat','ps1','sh'] as const).map(t => <button key={t} onClick={() => setScriptType(t)} className={`px-3 py-1.5 rounded-lg text-xs font-medium uppercase ${scriptType === t ? 'bg-emerald-600/20 text-emerald-400 border border-emerald-500/30' : isDark ? 'bg-[#1e2030] text-gray-400 border border-[#2a2b3d]' : 'bg-gray-100 text-gray-500 border border-gray-200'}`}>{t === 'bat' ? '.BAT' : t === 'ps1' ? '.PS1' : '.SH'}</button>)}</div><p className="text-xs text-gray-400 mb-3">Select ({selected.size}):</p><div className="grid grid-cols-2 gap-2 max-h-64 overflow-y-auto">{connections.map((c: SSHConnection) => <label key={c.id} className={`flex items-center gap-2 p-2 rounded-lg cursor-pointer ${selected.has(c.id) ? 'bg-emerald-600/10 border border-emerald-500/30' : isDark ? 'border border-transparent hover:bg-[#1e2030]' : 'hover:bg-gray-50'}`}><input type="checkbox" checked={selected.has(c.id)} onChange={() => toggle(c.id)} className="rounded" /><div className="w-2 h-2 rounded-full" style={{ backgroundColor: c.color }} /><span className={`text-xs ${isDark ? 'text-gray-300' : 'text-gray-700'}`}>{c.name}</span></label>)}</div><button onClick={generate} className="mt-4 w-full py-3 bg-emerald-600 hover:bg-emerald-500 rounded-lg text-white font-medium">Generate Script</button></div></div></div>); }

function ShortcutsView({ isDark, platform }: any) { return (<div className="flex-1 overflow-y-auto p-8"><div className="max-w-3xl mx-auto"><h1 className={`text-2xl font-bold mb-2 ${isDark ? 'text-white' : 'text-gray-900'}`}>Keyboard Shortcuts</h1><p className="text-sm text-gray-400 mb-6">{PLATFORMS[platform].icon} {PLATFORMS[platform].name} shortcuts</p><div className={`rounded-xl border overflow-hidden ${isDark ? 'bg-[#161822] border-[#1e2030]' : 'bg-white border-gray-200'}`}>{KEYBOARD_SHORTCUTS.map((s, i) => <div key={i} className={`flex items-center justify-between px-4 py-3 ${i > 0 ? `border-t ${isDark ? 'border-[#1e2030]' : 'border-gray-100'}` : ''}`}><span className={`text-sm ${isDark ? 'text-gray-300' : 'text-gray-700'}`}>{s.description}</span><kbd className={`px-2 py-1 rounded text-xs font-mono ${isDark ? 'bg-[#1e2030] text-gray-300 border border-[#2a2b3d]' : 'bg-gray-100 text-gray-600 border border-gray-200'}`}>{platform === 'macos' ? s.mac : s.keys}</kbd></div>)}</div></div></div>); }

function TemplatesView({ isDark, platform, onApply }: any) { return (<div className="flex-1 overflow-y-auto p-8"><div className="max-w-4xl mx-auto"><h1 className={`text-2xl font-bold mb-2 ${isDark ? 'text-white' : 'text-gray-900'}`}>Templates</h1><p className="text-sm text-gray-400 mb-6">{PLATFORMS[platform].icon} Pre-configured for {PLATFORMS[platform].name}</p><div className="grid grid-cols-2 md:grid-cols-3 gap-4">{CONNECTION_TEMPLATES.map((t, i) => <button key={i} onClick={() => onApply(t)} className={`p-4 rounded-xl border text-left ${isDark ? 'bg-[#161822] border-[#1e2030] hover:border-emerald-500/30' : 'bg-white border-gray-200 hover:border-emerald-300'}`}><p className={`text-sm font-semibold mb-1 ${isDark ? 'text-gray-200' : 'text-gray-800'}`}>{t.name}</p><p className="text-xs text-gray-500">{t.username}@{t.host || '<host>'}:{t.port}</p><div className="flex flex-wrap gap-1 mt-2">{t.tags?.map(tag => <span key={tag} className="px-1.5 py-0.5 bg-emerald-600/10 text-emerald-400 text-[10px] rounded">{tag}</span>)}</div><span className="text-[10px] text-gray-500 mt-2 block uppercase">{t.protocol}</span></button>)}</div></div></div>); }

function DocsView({ isDark, platform, settings }: any) {
  const [section, setSection] = useState('getting-started');
  const sections = [{ id: 'getting-started', label: 'Getting Started' }, { id: 'platforms', label: 'Cross-Platform' }, { id: 'zmodem', label: 'Zmodem/ZSSH' }, { id: 'github', label: 'GitHub' }, { id: 'file-transfer', label: 'File Transfer' }, { id: 'port-forwarding', label: 'Port Forwarding' }, { id: 'key-management', label: 'Key Management' }, { id: 'security', label: 'Security' }, { id: 'faq', label: 'FAQ' }];
  return (<div className="flex-1 flex overflow-hidden"><div className={`w-48 border-r overflow-y-auto p-3 ${isDark ? 'bg-[#161822] border-[#1e2030]' : 'bg-white border-gray-200'}`}><h3 className={`text-xs font-semibold uppercase tracking-wider mb-3 px-2 ${isDark ? 'text-gray-500' : 'text-gray-400'}`}>Docs</h3><div className="space-y-0.5">{sections.map(s => <button key={s.id} onClick={() => setSection(s.id)} className={`w-full text-left px-2.5 py-1.5 rounded-md text-xs ${section === s.id ? 'bg-emerald-600/20 text-emerald-400' : isDark ? 'text-gray-400 hover:bg-[#1e2030]' : 'text-gray-500 hover:bg-gray-100'}`}>{s.label}</button>)}</div></div><div className="flex-1 overflow-y-auto p-8"><div className="max-w-3xl mx-auto">
    {section === 'getting-started' && (<><h1 className={`text-2xl font-bold mb-4 ${isDark ? 'text-white' : 'text-gray-900'}`}>Getting Started</h1><div className="space-y-4"><DocSection title="Welcome" isDark={isDark}><p className="text-sm text-gray-400">SSH Manager Pro is a cross-platform SSH connection manager that works on <strong className="text-emerald-400">Windows</strong>, <strong className="text-emerald-400">macOS</strong>, and <strong className="text-emerald-400">Linux</strong>.</p></DocSection><DocSection title="Quick Start" isDark={isDark}><ol className="list-decimal list-inside space-y-2 text-sm text-gray-400"><li>Go to Settings and select your platform</li><li>Configure your preferred terminal</li><li>Add connections with the + button</li><li>Click Connect to generate platform-specific commands</li></ol></DocSection><DocSection title="Platform Detection" isDark={isDark}><p className="text-sm text-gray-400">Current platform: <strong className="text-emerald-400">{PLATFORMS[platform].icon} {PLATFORMS[platform].name}</strong></p><p className="text-sm text-gray-400 mt-2">All paths, commands, and terminal integrations adapt automatically to your OS.</p></DocSection></div></>)}
    {section === 'platforms' && (<><h1 className={`text-2xl font-bold mb-4 ${isDark ? 'text-white' : 'text-gray-900'}`}>Cross-Platform Support</h1><div className="space-y-4"><DocSection title="Windows 🪟" isDark={isDark}><div className="text-sm text-gray-400 space-y-2"><p><strong>Terminals:</strong> Windows Terminal, PowerShell, CMD, PuTTY, MobaXterm, Tabby</p><p><strong>Package Managers:</strong> winget, Scoop, Chocolatey</p><p><strong>SSH:</strong> Built-in OpenSSH (Windows 10+)</p><p><strong>RDP:</strong> mstsc (built-in)</p><p><strong>Paths:</strong> C:\Users\%USERNAME%\.ssh\</p></div></DocSection><DocSection title="macOS 🍎" isDark={isDark}><div className="text-sm text-gray-400 space-y-2"><p><strong>Terminals:</strong> iTerm2, Terminal.app, Warp, Alacritty, Tabby</p><p><strong>Package Manager:</strong> Homebrew</p><p><strong>SSH:</strong> Built-in OpenSSH</p><p><strong>VNC:</strong> Screen Sharing (built-in)</p><p><strong>Paths:</strong> ~/.ssh/</p></div></DocSection><DocSection title="Linux 🐧" isDark={isDark}><div className="text-sm text-gray-400 space-y-2"><p><strong>Terminals:</strong> GNOME Terminal, Konsole, XFCE Terminal, Tilix, Alacritty, Tabby</p><p><strong>Package Managers:</strong> APT, DNF, Pacman, Zypper</p><p><strong>SSH:</strong> OpenSSH (pre-installed)</p><p><strong>RDP:</strong> xfreerdp, Remmina</p><p><strong>Paths:</strong> ~/.ssh/</p></div></DocSection></div></>)}
    {section === 'zmodem' && (<><h1 className={`text-2xl font-bold mb-4 ${isDark ? 'text-white' : 'text-gray-900'}`}>Zmodem / ZSSH</h1><div className="space-y-4"><DocSection title={`Setup on ${PLATFORMS[platform].name}`} isDark={isDark}><CodeBlock code={generateZmodemSetup(platform, settings.packageManager)} isDark={isDark} /></DocSection><DocSection title="Commands" isDark={isDark}><div className="text-sm text-gray-400 space-y-1"><p><code className="text-emerald-400">sz file.txt</code> — Send file to local</p><p><code className="text-emerald-400">rz</code> — Receive file from local</p><p><code className="text-emerald-400">sz -be *.log</code> — Batch send</p></div></DocSection></div></>)}
    {section === 'github' && (<><h1 className={`text-2xl font-bold mb-4 ${isDark ? 'text-white' : 'text-gray-900'}`}>GitHub Integration</h1><div className="space-y-4"><DocSection title={`Setup on ${PLATFORMS[platform].name}`} isDark={isDark}><CodeBlock code={generateGitHubSetup(platform)} isDark={isDark} /></DocSection><DocSection title="SSH Agent" isDark={isDark}><CodeBlock code={generateSSHAgentSetup(platform)} isDark={isDark} /></DocSection></div></>)}
    {section === 'file-transfer' && (<><h1 className={`text-2xl font-bold mb-4 ${isDark ? 'text-white' : 'text-gray-900'}`}>File Transfer</h1><div className="space-y-4"><DocSection title="Methods" isDark={isDark}><div className="text-sm text-gray-400 space-y-2"><p><strong className="text-emerald-400">SCP</strong> — Simple file copy over SSH</p><p><strong className="text-emerald-400">SFTP</strong> — Interactive file management</p><p><strong className="text-emerald-400">Rsync</strong> — Efficient directory sync</p><p><strong className="text-emerald-400">Zmodem</strong> — Transfer within SSH session</p></div></DocSection></div></>)}
    {section === 'port-forwarding' && (<><h1 className={`text-2xl font-bold mb-4 ${isDark ? 'text-white' : 'text-gray-900'}`}>Port Forwarding</h1><div className="space-y-4"><DocSection title="Types" isDark={isDark}><div className="text-sm text-gray-400 space-y-2"><p><strong className="text-emerald-400">Local (-L)</strong> — Forward local port to remote</p><p><strong className="text-emerald-400">Remote (-R)</strong> — Forward remote port to local</p><p><strong className="text-emerald-400">Dynamic (-D)</strong> — SOCKS proxy</p></div></DocSection></div></>)}
    {section === 'key-management' && (<><h1 className={`text-2xl font-bold mb-4 ${isDark ? 'text-white' : 'text-gray-900'}`}>Key Management</h1><div className="space-y-4"><DocSection title="Generate Key" isDark={isDark}><CodeBlock code={generateKeyGenCommand('ed25519', 0, 'your@email.com', platform)} isDark={isDark} /></DocSection><DocSection title="SSH Agent" isDark={isDark}><CodeBlock code={generateSSHAgentSetup(platform)} isDark={isDark} /></DocSection></div></>)}
    {section === 'security' && (<><h1 className={`text-2xl font-bold mb-4 ${isDark ? 'text-white' : 'text-gray-900'}`}>Security</h1><div className="space-y-4"><DocSection title="Best Practices" isDark={isDark}><ul className="list-disc list-inside space-y-1 text-sm text-gray-400"><li>Use ED25519 keys</li><li>Protect keys with passphrases</li><li>Use jump hosts for internal servers</li><li>Set connection timeouts</li><li>Rotate keys periodically</li></ul></DocSection></div></>)}
    {section === 'faq' && (<><h1 className={`text-2xl font-bold mb-4 ${isDark ? 'text-white' : 'text-gray-900'}`}>FAQ</h1><div className="space-y-4"><DocSection title="Does it work on my OS?" isDark={isDark}><p className="text-sm text-gray-400">Yes! SSH Manager Pro is a web app that works on Windows, macOS, and Linux. All commands and paths adapt to your platform.</p></DocSection><DocSection title="How do I connect?" isDark={isDark}><p className="text-sm text-gray-400">Select a connection and click Connect. The platform-specific command is copied to your clipboard. Paste it in your terminal.</p></DocSection></div></>)}
  </div></div></div>);
}

function WelcomeScreen({ isDark, platform, onNew, count }: any) { return (<div className="flex-1 flex items-center justify-center p-8"><div className="max-w-lg text-center"><div className="w-20 h-20 mx-auto mb-6 bg-gradient-to-br from-emerald-500/20 to-blue-500/20 rounded-2xl flex items-center justify-center border border-emerald-500/20"><Terminal className="w-10 h-10 text-emerald-400" /></div><h2 className={`text-3xl font-bold mb-2 ${isDark ? 'text-white' : 'text-gray-900'}`}>SSH Manager Pro</h2><p className="text-gray-400 mb-2">Cross-platform SSH connection manager</p><p className="text-sm text-gray-500 mb-8">{PLATFORMS[platform].icon} {PLATFORMS[platform].name} • SSH • Zmodem • GitHub • RDP • VNC</p><button onClick={onNew} className="inline-flex items-center gap-2 px-6 py-3 bg-emerald-600 hover:bg-emerald-500 rounded-xl text-white font-medium"><Plus className="w-5 h-5" /> Add Connection</button><p className="text-xs text-gray-600 mt-4">{platform === 'macos' ? '⌘' : 'Ctrl'}+N • {count} connections</p></div></div>); }

function ToastItem({ toast, onDismiss }: { toast: Toast; onDismiss: () => void }) { const icons: Record<Toast['type'], React.ReactNode> = { success: <CheckCircle2 className="w-4 h-4 text-emerald-400" />, error: <XCircle className="w-4 h-4 text-red-400" />, warning: <AlertCircle className="w-4 h-4 text-amber-400" />, info: <Info className="w-4 h-4 text-blue-400" /> }; const borders: Record<Toast['type'], string> = { success: 'border-emerald-500/30', error: 'border-red-500/30', warning: 'border-amber-500/30', info: 'border-blue-500/30' }; return (<div className={`flex items-start gap-3 p-3 rounded-lg border shadow-xl bg-[#1a1b26] ${borders[toast.type]} min-w-[280px] max-w-[380px] animate-in slide-in-from-right`}>{icons[toast.type]}<div className="flex-1 min-w-0"><p className="text-sm font-medium text-white">{toast.title}</p><p className="text-xs text-gray-400 truncate">{toast.message}</p></div><button onClick={onDismiss} className="p-0.5 text-gray-500 hover:text-gray-300"><X className="w-3.5 h-3.5" /></button></div>); }
